window.BANK=[{"lv": "C4", "vis": "☀️", "q": "Kelompok mana yang semua anggotanya sumber cahaya alami (natural light source)?", "o": ["matahari, bintang, kunang-kunang", "lampu, senter, lilin", "matahari, lampu, obor", "bintang, lilin, senter"], "a": 0, "e": "Matahari, bintang, dan kunang-kunang membuat cahaya sendiri, jadi mereka sumber cahaya alami. Lampu, senter, lilin, dan obor dibuat oleh manusia."}, {"lv": "C4", "vis": "💡", "q": "Kelompok mana yang semua anggotanya sumber cahaya buatan (artificial light source)?", "o": ["lampu, senter, lilin", "matahari, bintang, lampu", "kilat, obor, kunang-kunang", "lilin, matahari, senter"], "a": 0, "e": "Lampu, senter, dan lilin dibuat oleh manusia, jadi disebut sumber cahaya buatan. Matahari, bintang, kilat, dan kunang-kunang berasal dari alam."}, {"lv": "C4", "vis": "🌙", "q": "Malam ini bulan terlihat terang di langit. Mengapa bulan bisa terlihat terang?", "o": ["Karena bulan membuat cahaya sendiri", "Karena bulan memantulkan cahaya matahari", "Karena bulan adalah bintang kecil", "Karena bulan menyerap cahaya lampu kota"], "a": 1, "e": "Bulan bukan sumber cahaya. Bulan terlihat terang karena memantulkan cahaya matahari (reflects sunlight)."}, {"lv": "C4", "vis": "🌑", "q": "Rina masuk ke kamar yang gelap. Lampu mati dan jendela tertutup. Mengapa Rina tidak bisa melihat mainannya?", "o": ["Mainannya sudah dipindahkan", "Tidak ada cahaya di kamar itu", "Mainannya berwarna gelap", "Rina lupa meletakkannya"], "a": 1, "e": "Mata butuh cahaya untuk melihat. Kamar gelap berarti tidak ada cahaya, jadi Rina tidak bisa melihat mainannya."}, {"lv": "C4", "vis": "👀", "q": "Pernyataan mana yang PALING BENAR tentang melihat (seeing)?", "o": ["Kita bisa melihat benda di tempat gelap tanpa cahaya", "Mata kita membutuhkan cahaya untuk melihat benda", "Benda gelap selalu bersinar sendiri", "Cahaya tidak penting saat melihat"], "a": 1, "e": "Mata kita membutuhkan cahaya (we need light to see). Di tempat gelap kita tidak bisa melihat benda."}, {"lv": "C4", "vis": "🧍", "q": "Ayu berdiri di depan lampu. Bayangannya muncul di dinding. Mengapa bayangan Ayu terbentuk?", "o": ["Karena dinding memantulkan cahaya", "Karena tubuh Ayu menghalangi cahaya lampu", "Karena lampu memberi warna pada tubuh Ayu", "Karena Ayu melihat ke dinding"], "a": 1, "e": "Bayangan (shadow) terbentuk saat cahaya terhalang benda. Tubuh Ayu menghalangi cahaya lampu, jadi bayangan muncul di dinding."}, {"lv": "C4", "vis": "⏰", "q": "Perhatikan waktu: pagi, siang, sore. Kapan bayanganmu di tanah paling pendek?", "o": ["Pagi hari", "Siang hari", "Sore hari", "Malam hari"], "a": 1, "e": "Saat siang, matahari berada tinggi di langit, jadi bayangan paling pendek (shortest shadow)."}, {"lv": "C4", "vis": "🌇", "q": "Pada sore hari, bayangan pohon menjadi lebih panjang daripada saat siang. Mengapa?", "o": ["Karena matahari berada lebih rendah di langit", "Karena pohon tumbuh lebih tinggi", "Karena cahaya matahari berwarna kuning", "Karena angin meniup bayangan"], "a": 0, "e": "Saat sore matahari lebih rendah di langit, jadi bayangan benda menjadi lebih panjang (longer shadow)."}, {"lv": "C4", "vis": "📏", "q": "Sebuah pensil panjang dan tipis diletakkan di bawah lampu. Bagaimana bentuk bayangannya?", "o": ["Panjang dan tipis seperti pensil", "Bulat seperti bola", "Kotak seperti buku", "Berbentuk bintang"], "a": 0, "e": "Bentuk bayangan mengikuti bentuk bendanya (shadow follows the shape of the object)."}, {"lv": "C4", "vis": "🪟", "q": "Kaca bening diletakkan di antara lampu dan dinding. Apa yang terjadi pada cahaya lampu?", "o": ["Cahaya menembus kaca bening", "Cahaya berhenti di kaca bening", "Kaca bening berubah menjadi gelap", "Cahaya berubah menjadi bayangan"], "a": 0, "e": "Benda bening seperti kaca meneruskan cahaya (let light pass through), jadi cahaya bisa lewat."}, {"lv": "C4", "vis": "📚", "q": "Apa perbedaan kaca bening dan buku tebal saat terkena cahaya lampu?", "o": ["Kaca bening meneruskan cahaya, buku tebal menghalangi cahaya", "Buku tebal meneruskan cahaya, kaca bening menghalangi cahaya", "Keduanya meneruskan semua cahaya", "Keduanya menghalangi semua cahaya"], "a": 0, "e": "Kaca bening meneruskan cahaya, sedangkan buku tebal menghalangi (blocks) cahaya sehingga terbentuk bayangan."}, {"lv": "C4", "vis": "😎", "q": "Ibu memakai kacamata hitam saat ke pantai pada siang hari. Mengapa?", "o": ["Agar sinar matahari yang terang tidak melukai mata", "Agar mata terlihat lebih besar", "Agar tidak bisa melihat apa pun", "Agar wajah menjadi dingin"], "a": 0, "e": "Sinar matahari sangat terang. Kita tidak boleh menatap matahari langsung karena bisa melukai mata."}, {"lv": "C4", "vis": "🌳", "q": "Di bawah pohon besar terasa sejuk dan ada bayangan gelap. Mengapa?", "o": ["Karena daun dan batang pohon menghalangi cahaya matahari", "Karena pohon mengeluarkan cahaya sendiri", "Karena matahari tidak menyinari bumi", "Karena pohon menyerap udara"], "a": 0, "e": "Daun dan batang pohon menghalangi cahaya matahari, jadi di bawah pohon terbentuk bayangan yang sejuk."}, {"lv": "C4", "vis": "🚩", "q": "Urutan panjang bayangan tiang bendera dari pagi sampai sore adalah ...", "o": ["panjang, pendek, panjang lagi", "pendek, panjang, pendek", "panjang, panjang, lalu pendek", "pendek, pendek, lalu panjang"], "a": 0, "e": "Pagi bayangan panjang, siang bayangan pendek, sore bayangan panjang lagi. Bayangan mengikuti posisi sumber cahaya (position of the light source)."}, {"lv": "C4", "vis": "⚡", "q": "Saat hujan badai, langit terang karena kilat. Kilat termasuk ...", "o": ["sumber cahaya alami", "sumber cahaya buatan", "bukan sumber cahaya", "cahaya dari lampu kota"], "a": 0, "e": "Kilat (lightning) berasal dari alam, jadi termasuk sumber cahaya alami."}, {"lv": "C4", "vis": "✨", "q": "Matahari bersinar pada siang hari, bintang bersinar pada malam hari, kunang-kunang bersinar di taman. Apa persamaan ketiganya?", "o": ["Ketiganya sumber cahaya alami", "Ketiganya dibuat oleh manusia", "Ketiganya memantulkan cahaya bulan", "Ketiganya benda mati"], "a": 0, "e": "Matahari, bintang, dan kunang-kunang membuat cahaya sendiri dan berasal dari alam, jadi sumber cahaya alami."}, {"lv": "C5", "vis": "🔦", "q": "Budi bermain di halaman saat malam. Halaman sangat gelap. Apa yang PALING TEPAT dilakukan Budi?", "o": ["Membawa dan menyalakan senter", "Menyalakan televisi di dalam rumah", "Menutup kedua matanya", "Memakai jaket tebal"], "a": 0, "e": "Senter adalah sumber cahaya buatan. Dengan senter, Budi bisa melihat halaman yang gelap dan bermain dengan aman."}, {"lv": "C5", "vis": "📸", "q": "Keluarga Dina berfoto di dalam ruangan yang gelap. Apa yang paling tepat dilakukan agar foto terlihat jelas?", "o": ["Menyalakan lampu ruangan yang terang", "Mematikan semua lampu", "Menutup semua tirai jendela", "Berfoto sambil memejamkan mata"], "a": 0, "e": "Foto butuh cahaya. Ruangan yang terang membuat foto terlihat jelas."}, {"lv": "C5", "vis": "🌞", "q": "Kamu ingin melihat gerhana matahari. Mana cara PALING AMAN untuk melihatnya?", "o": ["Menatap matahari langsung", "Memakai kacamata khusus untuk melihat matahari", "Melihat dengan teropong biasa", "Menutup satu mata lalu menatap lama"], "a": 1, "e": "Menatap matahari langsung bisa melukai mata. Kita harus memakai kacamata khusus pelindung matahari."}, {"lv": "C5", "vis": "👧", "q": "Maya ingin bayangannya terlihat jelas di dinding. Mana cara paling tepat?", "o": ["Menyalakan lampu yang mengarah ke tubuh Maya", "Mematikan semua lampu di rumah", "Duduk di ruangan yang gelap", "Pindah ke luar rumah saat malam"], "a": 0, "e": "Bayangan terbentuk saat ada cahaya yang terhalang benda. Lampu yang mengarah ke tubuh Maya membuat bayangan jelas di dinding."}, {"lv": "C5", "vis": "🏃", "q": "Siang ini bayangan Dito sangat pendek. Dito ingin bayangannya panjang. Kapan sebaiknya Dito bermain di halaman?", "o": ["Pagi atau sore hari", "Tepat saat siang hari", "Malam hari tanpa lampu", "Saat hujan deras"], "a": 0, "e": "Saat pagi atau sore, matahari rendah di langit, jadi bayangan menjadi panjang."}, {"lv": "C5", "vis": "📖", "q": "Lampu belajar Rara redup, jadi matanya cepat lelah. Apa yang paling tepat dilakukan Rara agar bisa belajar dengan nyaman?", "o": ["Mengganti lampu dengan yang lebih terang", "Membaca di ruangan gelap", "Membaca sambil berjalan", "Mengurangi cahaya lampu"], "a": 0, "e": "Cahaya yang cukup membuat mata nyaman saat membaca. Lampu yang redup membuat mata cepat lelah."}, {"lv": "C5", "vis": "⛺", "q": "Dina berkemah di dalam tenda. Malam tiba dan tenda menjadi gelap. Mana sumber cahaya yang PALING AMAN dibawa ke dalam tenda?", "o": ["Senter", "Lilin yang menyala", "Obor berapi", "Api unggun"], "a": 0, "e": "Senter aman digunakan di dalam tenda. Lilin, obor, dan api unggun berbahaya karena bisa membakar tenda."}, {"lv": "C5", "vis": "🪟", "q": "Rio ingin membaca buku saat cahaya matahari terang masuk ke rumahnya. Mana tempat PALING TEPAT untuk Rio?", "o": ["Dekat jendela yang terkena cahaya matahari", "Di dalam lemari yang tertutup", "Di bawah meja", "Di kamar yang lampunya mati"], "a": 0, "e": "Kita butuh cahaya untuk membaca. Tempat dekat jendela mendapat cahaya matahari yang cukup."}, {"lv": "C5", "vis": "🛣️", "q": "Matahari sore sangat silau saat Arif berjalan pulang. Apa yang PALING TEPAT dan AMAN dilakukan Arif?", "o": ["Memakai topi atau kacamata hitam, lalu berjalan dengan hati-hati", "Menatap matahari sambil berjalan", "Menutup kedua mata sambil menyeberang jalan", "Berlari cepat di tengah jalan"], "a": 0, "e": "Topi atau kacamata hitam melindungi mata dari silau. Kita tidak boleh menatap matahari langsung."}, {"lv": "C5", "vis": "🪞", "q": "Fatim menunjuk senter ke cermin. Cahaya memantul ke matanya dan membuat silau. Apa paling tepat dilakukan Fatim?", "o": ["Mengarahkan senter ke tempat lain", "Menatap cermin lebih dekat", "Menyalakan lampu yang lebih besar", "Duduk diam di depan cermin"], "a": 0, "e": "Senter bisa membuat mata silau. Fatim sebaiknya mengarahkan senter (flashlight) ke tempat lain."}, {"lv": "C5", "vis": "🍽️", "q": "Malam ini lampu rumah mati. Keluarga Andi ingin makan bersama. Mana yang PALING TEPAT dilakukan?", "o": ["Menyalakan lampu darurat atau lilin di meja dengan hati-hati", "Makan dalam gelap", "Menunggu sampai pagi", "Menyalakan kipas angin"], "a": 0, "e": "Lampu darurat atau lilin memberi cahaya saat mati lampu. Gunakan dengan hati-hati agar aman."}, {"lv": "C6", "vis": "🌅", "q": "Kamu ingin bayanganmu di tanah menjadi LEBIH PANJANG. Rencana mana yang paling tepat?", "o": ["Bermain di halaman pada pagi atau sore hari saat matahari rendah", "Bermain tepat saat siang hari", "Bermain di kamar yang gelap", "Duduk di bawah pohon besar"], "a": 0, "e": "Cahaya matahari yang rendah di pagi atau sore hari membuat bayangan lebih panjang (longer shadow)."}, {"lv": "C6", "vis": "🏫", "q": "Ruangan kelasmu menjadi gelap karena lampu mati saat siang hari. Rencana apa yang paling tepat agar kelas menjadi terang?", "o": ["Membuka tirai dan jendela agar cahaya matahari masuk", "Menutup semua pintu dan jendela", "Menyalakan televisi di depan kelas", "Memakai jaket agar tidak dingin"], "a": 0, "e": "Pada siang hari ada cahaya matahari. Membuka jendela dan tirai membuat cahaya masuk sehingga kelas menjadi terang."}, {"lv": "C6", "vis": "🎭", "q": "Kamu ingin membuat pertunjukan bayangan tangan di dinding kamar. Rencana mana yang paling tepat?", "o": ["Menyalakan lampu, meletakkan tangan di antara lampu dan dinding, lalu menggerakkan tangan", "Meletakkan tangan di belakang dinding, lalu mematikan lampu", "Duduk di kamar gelap tanpa menyalakan lampu", "Menutup dinding dengan selimut tebal"], "a": 0, "e": "Bayangan terbentuk saat cahaya terhalang benda. Lampu dan tangan di depannya membuat bayangan di dinding."}, {"lv": "C4", "vis": "🔌", "q": "Benda mana yang TIDAK bekerja dengan listrik?", "o": ["Kulkas", "Sapu", "Setrika", "Radio"], "a": 1, "e": "Sapu dipakai dengan tenaga tangan, jadi tidak butuh listrik. Kulkas, setrika, dan radio bekerja dengan listrik."}, {"lv": "C4", "vis": "🔋", "q": "Benda mana yang memakai listrik dari baterai?", "o": ["Senter", "Kulkas", "Mesin cuci", "TV"], "a": 0, "e": "Senter memakai baterai (battery) kecil di dalamnya. Kulkas, mesin cuci, dan TV harus dicolok ke stopkontak."}, {"lv": "C4", "vis": "🏠", "q": "Benda mana yang harus dicolok ke stopkontak di dinding rumah?", "o": ["Remote TV", "Senter kecil", "Kulkas", "Mobil mainan baterai"], "a": 2, "e": "Kulkas butuh listrik besar dari colokan rumah. Remote, senter, dan mobil mainan cukup memakai baterai."}, {"lv": "C4", "vis": "💡", "q": "Rina menekan sakelar lampu ke posisi OFF. Apa yang terjadi pada lampu?", "o": ["Lampu makin terang", "Lampu mati", "Lampu berubah warna", "Lampu berbunyi"], "a": 1, "e": "Sakelar (switch) pada posisi OFF memutus aliran listrik, jadi lampu mati."}, {"lv": "C4", "vis": "🔗", "q": "Kabel pada rangkaian lampu terlepas sehingga ada celah. Apa yang terjadi pada lampu?", "o": ["Lampu menyala makin terang", "Lampu mati karena rangkaian putus", "Lampu menjadi panas", "Lampu berputar"], "a": 1, "e": "Listrik hanya mengalir pada rangkaian tertutup. Jika kabel putus, arus listrik terhenti dan lampu mati."}, {"lv": "C4", "vis": "🛡️", "q": "Mengapa kabel listrik aman disentuh dari bagian luarnya?", "o": ["Karena kabel dilapisi plastik", "Karena kabel terbuat dari air", "Karena kabel berwarna hitam", "Karena kabel berisi benang"], "a": 0, "e": "Plastik di luar kabel disebut isolasi. Plastik tidak menghantarkan listrik, jadi kabel aman disentuh."}, {"lv": "C4", "vis": "🌀", "q": "Benda mana yang bagiannya berputar karena ada motor listrik?", "o": ["Setrika", "Kipas angin", "Lampu", "Bel"], "a": 1, "e": "Kipas angin memakai motor (motor) yang berputar dan menggerakkan baling-balingnya."}, {"lv": "C4", "vis": "🔔", "q": "Bel rumah berbunyi. Bagian apa yang membuat suaranya?", "o": ["Motor", "Buzzer", "Lampu", "Kabel"], "a": 1, "e": "Buzzer adalah bagian yang mengubah listrik menjadi suara, misalnya pada bel rumah."}, {"lv": "C4", "vis": "📻", "q": "Alat mana yang mengubah listrik menjadi SUARA?", "o": ["Lampu", "Setrika", "Radio", "Kipas angin"], "a": 2, "e": "Radio mengubah listrik menjadi suara. Lampu menjadi cahaya, setrika menjadi panas, kipas menjadi gerakan."}, {"lv": "C4", "vis": "♨️", "q": "Setrika listrik menjadi panas, lampu listrik menjadi terang. Artinya listrik dapat berubah menjadi ... dan ...", "o": ["panas dan cahaya", "cahaya dan suara", "gerakan dan dingin", "suara dan dingin"], "a": 0, "e": "Setrika menghasilkan panas (heat), lampu menghasilkan cahaya (light). Listrik bisa berubah menjadi panas dan cahaya."}, {"lv": "C4", "vis": "🎮", "q": "Kelompok mana yang semuanya memakai baterai?", "o": ["Senter, remote TV, dan mobil mainan", "Kulkas, TV, dan mesin cuci", "Sapu, pensil, dan buku", "Setrika, kipas angin, dan radio"], "a": 0, "e": "Senter, remote, dan mobil mainan memakai baterai. Kulkas, TV, dan mesin cuci dicolok ke stopkontak, sedangkan sapu, pensil, dan buku tidak butuh listrik."}, {"lv": "C4", "vis": "🔍", "q": "Sakelar lampu sudah ditekan ON, tetapi lampu tetap mati. Apa yang paling mungkin menjadi penyebabnya?", "o": ["Baterainya habis", "Sakelarnya terlalu besar", "Lampunya berwarna putih", "Kabelnya terlalu panjang"], "a": 0, "e": "Lampu bisa tetap mati jika baterainya habis, karena listrik tidak mengalir ke lampu."}, {"lv": "C4", "vis": "⚡", "q": "Perhatikan tiga rangkaian!\nRangkaian A: baterai, kabel, dan lampu tersambung penuh.\nRangkaian B: kabelnya putus.\nRangkaian C: tidak ada baterai.\nRangkaian mana yang lampunya menyala?", "o": ["Rangkaian A", "Rangkaian B", "Rangkaian C", "Semua rangkaian"], "a": 0, "e": "Rangkaian (circuit) butuh baterai, kabel yang tersambung, dan lampu. Hanya rangkaian A yang lengkap dan tertutup."}, {"lv": "C4", "vis": "🧺", "q": "Mana yang sumber listriknya BERBEDA dari yang lain?", "o": ["Senter", "Remote TV", "Kulkas", "Mobil mainan"], "a": 2, "e": "Senter, remote, dan mobil mainan memakai baterai. Kulkas memakai listrik dari colokan rumah."}, {"lv": "C4", "vis": "🚪", "q": "Bel rumah berbunyi saat tombol ditekan dan berhenti saat tombol dilepas. Tombol itu bekerja seperti ...", "o": ["sakelar (switch)", "baterai", "lampu", "kabel"], "a": 0, "e": "Tombol bel bekerja seperti sakelar: menekan berarti ON sehingga arus mengalir, melepas berarti OFF."}, {"lv": "C4", "vis": "🌡️", "q": "Alat A menjadi panas saat dinyalakan. Alat B menjadi berputar saat dinyalakan. Alat A dan B adalah ...", "o": ["setrika dan kipas angin", "lampu dan radio", "bel dan TV", "pensil dan buku"], "a": 0, "e": "Setrika berubah menjadi panas, kipas angin berputar karena motor."}, {"lv": "C5", "vis": "💧", "q": "Tanganmu basah dan kamu mau menyalakan lampu. Apa yang PALING aman dilakukan?", "o": ["Mengeringkan tangan dulu, lalu menekan sakelar", "Langsung menekan sakelar dengan tangan basah", "Menekan sakelar sambil memegang air", "Minta adik menekan sakelar dengan tangan basah"], "a": 0, "e": "Air menghantarkan listrik. Tangan harus kering sebelum menyentuh sakelar atau colokan agar tidak tersetrum."}, {"lv": "C5", "vis": "🪁", "q": "Layang-layangmu terbang dekat kabel listrik besar. Apa yang paling aman dilakukan?", "o": ["Menarik layang-layang menjauh dari kabel", "Membiarkan layang-layang di dekat kabel", "Menaiki atap untuk mengambil layang-layang", "Menarik layang-layang dengan kawat besi"], "a": 0, "e": "Bermain layang-layang dekat kabel listrik sangat berbahaya. Jauhkan layang-layang dari kabel listrik."}, {"lv": "C5", "vis": "🔌", "q": "Bagaimana cara paling aman mencabut charger dari stopkontak?", "o": ["Memegang kepala colokannya, lalu menariknya perlahan", "Menarik kabelnya kuat-kuat", "Menarik kabel dengan tangan basah", "Mencongkelnya dengan sendok"], "a": 0, "e": "Cabut charger dengan memegang kepala colokan (plug), bukan kabelnya, supaya kabel tidak rusak dan aman."}, {"lv": "C5", "vis": "🚫", "q": "Adikmu mau memasukkan pensil ke lubang stopkontak. Apa yang paling tepat kamu lakukan?", "o": ["Mencegah adik dan menjelaskan bahayanya", "Membantu adik memasukkan pensil", "Membiarkan saja", "Ikut memasukkan benda lain"], "a": 0, "e": "Lubang stopkontak berisi listrik. Jangan pernah memasukkan benda apa pun ke dalamnya."}, {"lv": "C5", "vis": "🌙", "q": "Kamu keluar dari kamar, tetapi lampu masih menyala. Apa pilihan paling hemat listrik?", "o": ["Mematikan lampu sebelum keluar kamar", "Membiarkan lampu tetap menyala", "Menyalakan lampu lain juga", "Menutup lampu dengan kain"], "a": 0, "e": "Mematikan lampu saat tidak dipakai adalah cara menghemat listrik."}, {"lv": "C5", "vis": "🌀", "q": "Kipas angin tidak mau berputar saat dinyalakan. Apa yang paling baik kamu lakukan?", "o": ["Memberi tahu orang dewasa untuk memeriksanya", "Membongkar kipas sendiri", "Memasukkan tangan ke dalam kipas", "Menusuk kipas dengan pensil"], "a": 0, "e": "Alat listrik yang rusak harus diperiksa orang dewasa. Anak-anak tidak boleh membongkar atau menyentuh bagian dalamnya."}, {"lv": "C5", "vis": "🔋", "q": "Lampu sentermu mati. Kamu sudah menekan tombolnya, tetapi tetap mati. Apa pilihan paling tepat?", "o": ["Mengganti baterainya dengan yang baru", "Mencuci senter dengan air", "Melempar senter", "Membuka lampu senter dengan pisau"], "a": 0, "e": "Baterai yang habis membuat senter mati. Ganti baterai dengan yang baru."}, {"lv": "C5", "vis": "🧩", "q": "Lampu rangkaianmu tidak menyala. Sakelar sudah ON dan baterainya baru. Apa yang paling baik diperiksa lebih dulu?", "o": ["Kabel yang mungkin lepas atau putus", "Warna kabelnya", "Ukuran lampunya", "Nama lampunya"], "a": 0, "e": "Jika baterai dan sakelar baik, penyebab paling mungkin adalah kabel yang lepas atau putus sehingga rangkaian tidak tertutup."}, {"lv": "C5", "vis": "♨️", "q": "Setrika baru saja dipakai dan masih panas. Apa yang paling aman dilakukan?", "o": ["Tidak menyentuhnya dan menunggu sampai dingin", "Menyentuhnya dengan tangan", "Menyiramnya dengan air sambil dipegang", "Menarik kabelnya dari stopkontak sambil bermain"], "a": 0, "e": "Setrika panas bisa melukai tangan. Tunggu sampai dingin sebelum disentuh, dan minta bantuan orang dewasa."}, {"lv": "C5", "vis": "🧵", "q": "Kabel mainanmu mulai terkelupas. Apa yang paling aman?", "o": ["Berhenti memakainya dan memberi tahu orang dewasa", "Terus memakainya", "Menutup kabel dengan tangan", "Membasahi kabelnya"], "a": 0, "e": "Kabel yang terkelupas berbahaya karena bagian dalamnya bisa tersentuh. Jangan dipakai sampai diperbaiki."}, {"lv": "C5", "vis": "📺", "q": "Mana kebiasaan paling baik untuk menghemat listrik di rumah?", "o": ["Mematikan TV saat tidak ditonton", "Menyalakan semua lampu siang dan malam", "Membiarkan pintu kulkas terbuka", "Menyalakan kipas dan lampu di kamar kosong"], "a": 0, "e": "Matikan alat listrik saat tidak dipakai. Ini menghemat listrik."}, {"lv": "C6", "vis": "💡", "q": "Kamu ingin membuat lampu kecil menyala. Bahan apa yang kamu butuhkan?", "o": ["Baterai, kabel, dan lampu", "Buku, pensil, dan sapu", "Air, sendok, dan gelas", "Kertas, lem, dan gunting"], "a": 0, "e": "Untuk membuat rangkaian (circuit) sederhana, kamu perlu baterai sebagai sumber listrik, kabel untuk mengalirkan listrik, dan lampu yang akan menyala."}, {"lv": "C6", "vis": "🚗", "q": "Kamu membuat mobil mainan dari kardus. Agar rodanya bisa berputar, kamu menambahkan ...", "o": ["motor kecil dan baterai", "buzzer dan lampu", "setrika kecil", "sakelar saja tanpa baterai"], "a": 0, "e": "Motor (motor) mengubah listrik menjadi gerakan. Motor kecil yang diberi baterai bisa memutar roda mobil mainan."}, {"lv": "C6", "vis": "🏠", "q": "Kamu membuat daftar aturan aman memakai listrik untuk adikmu di rumah. Aturan mana yang paling tepat ditulis?", "o": ["Keringkan tangan sebelum menyentuh sakelar dan jangan menarik kabel", "Bermainlah dengan stopkontak saat bosan", "Tarik kabel sekuat mungkin saat mencabut", "Main layang-layang dekat kabel listrik"], "a": 0, "e": "Aturan aman memakai listrik: tangan harus kering, jangan menarik kabel, jangan bermain di stopkontak, dan jangan bermain layang-layang dekat kabel listrik."}, {"lv": "C4", "vis": "☀️", "q": "Rani melihat cahaya masuk lewat jendela pada pagi hari, lalu ia menyalakan lampu meja.\nManakah yang termasuk sumber cahaya alami?", "o": ["Lampu meja", "Matahari", "Senter", "Lilin"], "a": 1, "e": "Matahari adalah sumber cahaya alami karena cahayanya berasal dari alam (natural light source)."}, {"lv": "C4", "vis": "🌙", "q": "Di malam hari Ayah menyalakan lampu, sedangkan bintang bersinar di langit.\nManakah yang termasuk sumber cahaya buatan?", "o": ["Bintang", "Bulan", "Lampu", "Matahari"], "a": 2, "e": "Lampu dibuat oleh manusia sehingga termasuk sumber cahaya buatan (artificial light source)."}, {"lv": "C4", "vis": "🌑", "q": "Bagas berada di kamar dengan tirai tertutup dan lampu mati.\nMengapa Bagas tidak dapat melihat benda di sekitarnya?", "o": ["Karena matanya tertutup", "Karena tidak ada cahaya di kamar", "Karena bendanya hilang", "Karena kamar terlalu luas"], "a": 1, "e": "Kita melihat benda karena ada cahaya; tanpa cahaya (light) kita tidak dapat melihat."}, {"lv": "C4", "vis": "🔥", "q": "Perhatikan daftar berikut!\n(1) lilin (2) bulan (3) lampu senter (4) kunang-kunang\nManakah yang semuanya sumber cahaya buatan?", "o": ["1 dan 2", "1 dan 3", "2 dan 4", "3 dan 4"], "a": 1, "e": "Lilin dan lampu senter dibuat manusia, jadi termasuk sumber cahaya buatan (artificial light source)."}, {"lv": "C4", "vis": "💡", "q": "Saat sore hari, cahaya matahari di teras mulai redup.\nApa yang paling tepat dilakukan agar ruangan tetap terang?", "o": ["Menutup semua tirai", "Menyalakan lampu ruangan", "Mematikan sakelar", "Menutup pintu"], "a": 1, "e": "Menyalakan lampu menambah cahaya sehingga ruangan lebih terang (brighter)."}, {"lv": "C4", "vis": "📖", "q": "Ayu membaca buku di ruangan yang redup sehingga tulisannya sulit terlihat.\nApa yang sebaiknya Ayu lakukan?", "o": ["Menjauhkan buku dari mata", "Menambah cahaya dengan menyalakan lampu", "Menutup bukunya", "Memakai kacamata hitam"], "a": 1, "e": "Menambah cahaya membuat tulisan lebih jelas terlihat (clearer)."}, {"lv": "C4", "vis": "🪞", "q": "Dina bercermin dan melihat wajahnya.\nMengapa Dina dapat melihat wajahnya di cermin?", "o": ["Cahaya diserap oleh cermin", "Cahaya dipantulkan oleh cermin", "Cermin menyalakan cahaya sendiri", "Wajah Dina masuk ke dalam cermin"], "a": 1, "e": "Cermin memantulkan cahaya (reflection) sehingga kita melihat bayangan diri."}, {"lv": "C4", "vis": "✨", "q": "Permukaan mana yang paling banyak memantulkan cahaya seperti cermin?", "o": ["Kain hitam", "Sendok mengkilap", "Kertas buram", "Kayu kasar"], "a": 1, "e": "Benda mengkilap memantulkan cahaya paling banyak (shiny surface reflects light)."}, {"lv": "C4", "vis": "🪟", "q": "Cahaya dapat menembus benda bening.\nManakah kelompok benda bening?", "o": ["Kaca jendela, air jernih, gelas bening", "Buku, kayu, batu", "Kain, kertas, kardus", "Tembok, pintu, meja"], "a": 0, "e": "Kaca, air jernih, dan gelas bening adalah benda bening (transparent) yang ditembus cahaya."}, {"lv": "C4", "vis": "📚", "q": "Rina memegang buku di depan lampu. Di belakang buku terbentuk bayangan gelap.\nMengapa hal itu terjadi?", "o": ["Buku memantulkan semua cahaya", "Buku menghalangi cahaya sehingga tidak menembus", "Buku menyerap cahaya matahari", "Buku menyalakan cahaya sendiri"], "a": 1, "e": "Buku adalah benda gelap (opaque) yang menghalangi cahaya sehingga terbentuk bayangan."}, {"lv": "C4", "vis": "🏳️", "q": "Pada pagi hari bayangan tiang bendera panjang. Pada siang hari bayangan itu pendek.\nMengapa bayangan menjadi pendek saat siang?", "o": ["Matahari lebih dekat ke tiang", "Matahari berada tinggi di langit", "Tiang bendera memendek", "Angin bertiup kencang"], "a": 1, "e": "Saat matahari tinggi di langit, bayangan menjadi pendek (shorter shadow)."}, {"lv": "C4", "vis": "🌳", "q": "Sore hari bayangan pohon lebih panjang daripada saat tengah hari.\nMengapa demikian?", "o": ["Matahari sore lebih rendah di langit", "Pohon tumbuh menjadi tinggi", "Bayangan sore lebih gelap", "Angin menggeser bayangan"], "a": 0, "e": "Semakin rendah matahari, semakin panjang bayangan (longer shadow)."}, {"lv": "C4", "vis": "🤲", "q": "Sari menyalakan lampu dan menaruh tangannya di depan lampu sehingga terbentuk bayangan tangan di dinding.\nApa yang membuat bayangan tangan terbentuk?", "o": ["Warna dinding", "Tangan menghalangi cahaya lampu", "Lampu berwarna", "Bayangan menyalakan lampu"], "a": 1, "e": "Tangan menghalangi cahaya sehingga terbentuk bayangan (hand shadow)."}, {"lv": "C4", "vis": "🖐️", "q": "Bila tangan Sari didekatkan ke lampu, bayangan di dinding menjadi lebih besar.\nMengapa?", "o": ["Tangan menjadi besar", "Cahaya makin sedikit", "Bayangan tangan makin dekat ke sumber cahaya", "Dinding bergerak"], "a": 2, "e": "Semakin dekat benda ke sumber cahaya, bayangan semakin besar."}, {"lv": "C4", "vis": "🌈", "q": "Pelangi terbentuk dari cahaya matahari.\nWarna cahaya apa yang sering kita lihat pada pelangi?", "o": ["Hitam dan putih", "Merah, jingga, kuning, hijau, biru", "Hanya merah", "Hanya biru"], "a": 1, "e": "Cahaya matahari (white light) terdiri atas banyak warna seperti merah, kuning, hijau, dan biru."}, {"lv": "C4", "vis": "🔺", "q": "Cahaya putih dari matahari bila diuraikan akan menghasilkan banyak warna.\nAlat apa yang dapat menguraikan cahaya matahari menjadi warna-warna?", "o": ["Cermin datar", "Prisma", "Kain hitam", "Kayu"], "a": 1, "e": "Prisma menguraikan cahaya putih menjadi warna-warna (spectrum)."}, {"lv": "C4", "vis": "😎", "q": "Saat gerhana matahari, Doni ingin melihat matahari.\nApa yang sebaiknya Doni lakukan?", "o": ["Melihat langsung tanpa alat", "Memakai kacamata khusus gerhana", "Menutup mata sambil melihat", "Memakai kacamata hitam biasa"], "a": 1, "e": "Mata harus dilindungi dari cahaya sangat terang (eye safety) dengan kacamata khusus gerhana."}, {"lv": "C4", "vis": "🪞", "q": "Manakah benda yang tidak menghasilkan cahaya sendiri?", "o": ["Lilin menyala", "Matahari", "Cermin", "Lampu"], "a": 2, "e": "Cermin tidak menghasilkan cahaya sendiri, hanya memantulkan cahaya (reflects light)."}, {"lv": "C4", "vis": "🏠", "q": "Di satu ruangan ada satu lampu kecil, di ruangan lain ada tiga lampu besar.\nRuangan mana yang lebih terang?", "o": ["Ruangan dengan satu lampu kecil", "Ruangan dengan tiga lampu besar", "Keduanya sama terang", "Tidak ada yang terang"], "a": 1, "e": "Lebih banyak cahaya membuat ruangan lebih terang (brighter)."}, {"lv": "C4", "vis": "🚪", "q": "Mengapa kita dapat melihat keluar melalui kaca jendela tetapi tidak melalui pintu kayu?", "o": ["Kaca menyerap cahaya", "Kaca bening ditembus cahaya, kayu tidak", "Kayu lebih tipis", "Pintu berwarna"], "a": 1, "e": "Kaca bening (transparent) ditembus cahaya; kayu (opaque) tidak ditembus cahaya."}, {"lv": "C4", "vis": "🚗", "q": "Cermin dipasang di dalam mobil agar pengemudi dapat melihat kendaraan di belakang.\nSifat cahaya apa yang dimanfaatkan?", "o": ["Cahaya dipantulkan oleh cermin", "Cahaya diserap oleh cermin", "Cahaya menembus cermin", "Cahaya berwarna-warni"], "a": 0, "e": "Cermin memantulkan cahaya (reflection) sehingga pengemudi dapat melihat ke belakang."}, {"lv": "C4", "vis": "🌗", "q": "Bayangan terbentuk di sisi yang berlawanan dengan sumber cahaya.\nJika lampu berada di sebelah kiri benda, bayangan akan terbentuk di sebelah...", "o": ["Kanan", "Kiri", "Atas", "Bawah"], "a": 0, "e": "Bayangan terbentuk di sisi berlawanan dari sumber cahaya (opposite side)."}, {"lv": "C4", "vis": "🕊️", "q": "Bentuk bayangan mengikuti bentuk bendanya. Jika kita membuat bayangan dengan tangan berbentuk burung, bayangan di dinding akan berbentuk...", "o": ["Bunga", "Burung", "Rumah", "Mobil"], "a": 1, "e": "Bentuk bayangan mengikuti bentuk benda yang menghalangi cahaya."}, {"lv": "C4", "vis": "🕯️", "q": "Ketika lampu mati, Ibu menyalakan lilin.\nLilin termasuk sumber cahaya...", "o": ["Alami", "Buatan", "Pemantulan", "Bening"], "a": 1, "e": "Lilin dinyalakan oleh manusia sehingga termasuk sumber cahaya buatan (artificial)."}, {"lv": "C4", "vis": "🏖️", "q": "Rina memakai kacamata hitam saat ke pantai pada siang hari.\nApa manfaatnya?", "o": ["Agar mata terlindung dari cahaya terang", "Agar terlihat lucu", "Agar mata menjadi gelap", "Agar bisa melihat matahari"], "a": 0, "e": "Kacamata hitam melindungi mata dari cahaya terang (bright light)."}, {"lv": "C4", "vis": "🌤️", "q": "Mengapa di bawah pohon pada siang hari terasa lebih sejuk dan cahayanya lebih redup?", "o": ["Daun menghalangi sebagian cahaya matahari", "Daun menyalakan cahaya", "Pohon menyerap panas matahari", "Matahari menjauh dari pohon"], "a": 0, "e": "Daun menghalangi sebagian cahaya sehingga tempat di bawahnya lebih redup (dimmer)."}, {"lv": "C4", "vis": "🔦", "q": "Andi ingin membuat bayangan tangannya lebih jelas di dinding.\nApa yang sebaiknya Andi lakukan?", "o": ["Menjauhkan tangan dari lampu", "Mendekatkan tangan ke lampu", "Mematikan lampu", "Menutup dinding"], "a": 1, "e": "Mendekatkan benda ke sumber cahaya membuat bayangan lebih besar dan lebih jelas."}, {"lv": "C5", "vis": "📄", "q": "Rani menutup jendela dengan kertas tebal, sehingga ruangan menjadi gelap.\nKesimpulan apa yang tepat?", "o": ["Kertas bening ditembus cahaya", "Kertas menghalangi cahaya matahari", "Kertas menyalakan cahaya", "Cahaya menembus kertas"], "a": 1, "e": "Kertas tebal adalah benda gelap yang menghalangi cahaya (blocks light) sehingga ruangan gelap."}, {"lv": "C5", "vis": "🥛", "q": "Budi memakai dua gelas: gelas bening dan gelas berwarna gelap.\nManakah yang membuat lampu di belakangnya paling jelas terlihat?", "o": ["Gelas bening", "Gelas gelap", "Keduanya sama", "Tidak terlihat sama sekali"], "a": 0, "e": "Benda bening (transparent) meneruskan cahaya lebih baik daripada benda gelap."}, {"lv": "C5", "vis": "🌲", "q": "Sebuah pohon tinggi dan sebuah tiang kecil berdiri di halaman. Pada sore hari, bayangan mana yang lebih panjang?", "o": ["Bayangan tiang kecil", "Bayangan pohon yang tinggi", "Sama panjang", "Tidak ada bayangan"], "a": 1, "e": "Benda yang lebih tinggi menghasilkan bayangan yang lebih panjang (taller object, longer shadow)."}, {"lv": "C5", "vis": "⬛", "q": "Mengapa bayangan selalu berwarna gelap?", "o": ["Karena tidak ada cahaya yang sampai ke daerah bayangan", "Karena bayangan dicat hitam", "Karena bendanya berwarna gelap", "Karena matahari berwarna gelap"], "a": 0, "e": "Daerah bayangan tidak menerima cahaya sehingga tampak gelap (dark)."}, {"lv": "C5", "vis": "📚", "q": "Ayu ingin membaca di tempat yang paling terang.\nTempat mana yang sebaiknya dipilih?", "o": ["Di bawah meja", "Di dekat jendela pada siang hari", "Di kamar yang gelap", "Di bawah tempat tidur"], "a": 1, "e": "Dekat jendela pada siang hari mendapat banyak cahaya sehingga paling terang (brightest)."}, {"lv": "C5", "vis": "🕯️", "q": "Saat membuat bayangan tangan, Sari mematikan salah satu dari dua lampu.\nApa yang terjadi pada bayangan?", "o": ["Bayangan makin terang", "Bayangan makin samar/redup", "Bayangan hilang warna", "Bayangan tidak berubah"], "a": 1, "e": "Mengurangi cahaya membuat bayangan makin samar (less clear)."}, {"lv": "C5", "vis": "🗣️", "q": "Ani berkata 'cermin menghasilkan cahaya sendiri'. Beni berkata 'cermin hanya memantulkan cahaya'.\nSiapa yang benar?", "o": ["Ani", "Beni", "Keduanya benar", "Tidak ada yang benar"], "a": 1, "e": "Cermin tidak menghasilkan cahaya; ia memantulkan cahaya (reflects light)."}, {"lv": "C5", "vis": "🧢", "q": "Di pantai, cahaya matahari sangat terang.\nMengapa sebaiknya memakai topi lebar?", "o": ["Melindungi mata dari cahaya terang", "Agar tidak kehujanan", "Agar terlihat bagus", "Untuk menambah cahaya"], "a": 0, "e": "Topi lebar melindungi mata dari cahaya terang (bright light)."}, {"lv": "C5", "vis": "➡️", "q": "Kesimpulan: cahaya merambat lurus. Jika sebuah benda menghalangi cahaya, apa yang terjadi di belakangnya?", "o": ["Cahaya berbelok", "Terbentuk bayangan", "Cahaya berhenti selamanya", "Benda menjadi bercahaya"], "a": 1, "e": "Karena cahaya merambat lurus, benda menghalanginya sehingga terbentuk bayangan (shadow)."}, {"lv": "C5", "vis": "🔆", "q": "Ibu memasang lampu besar di ruang tamu, Ayah memasang lampu kecil di kamar.\nRuangan mana yang cenderung lebih redup?", "o": ["Ruang tamu", "Kamar", "Keduanya sama", "Keduanya terang"], "a": 1, "e": "Lampu kecil memberi cahaya lebih sedikit sehingga lebih redup (dimmer)."}, {"lv": "C5", "vis": "📦", "q": "Perhatikan tabel berikut!\nBenda A = kaca, Benda B = kardus, Benda C = air jernih.\nBenda mana yang menghalangi cahaya?", "o": ["Benda A", "Benda B", "Benda C", "Benda A dan C"], "a": 1, "e": "Kardus adalah benda gelap (opaque) yang menghalangi cahaya."}, {"lv": "C5", "vis": "🌃", "q": "Mengapa pada malam hari kita menyalakan lampu untuk membaca?", "o": ["Agar ada cahaya untuk melihat", "Agar buku berwarna", "Agar mata tertutup", "Agar listrik cepat habis"], "a": 0, "e": "Tanpa cahaya kita tidak bisa melihat, jadi perlu lampu (need light to see)."}, {"lv": "C5", "vis": "🌅", "q": "Bagas berdiri membelakangi matahari pagi.\nKe arah mana bayangan Bagas jatuh?", "o": ["Ke depan Bagas", "Ke belakang Bagas", "Ke atas", "Ke bawah"], "a": 0, "e": "Bayangan jatuh ke arah berlawanan dengan matahari, yaitu di depan Bagas."}, {"lv": "C5", "vis": "🧊", "q": "Kesimpulan mana yang benar tentang cahaya dan benda bening?", "o": ["Benda bening menyerap semua cahaya", "Benda bening meneruskan cahaya", "Benda bening memantulkan semua cahaya", "Benda bening menghalangi cahaya"], "a": 1, "e": "Benda bening meneruskan/menembuskan cahaya (transmit light)."}, {"lv": "C5", "vis": "🔦", "q": "Rani menyalakan lampu belajar yang redup saat membaca. Setelah diganti lampu yang lebih terang, apa yang berubah?", "o": ["Tulisan makin sulit dilihat", "Tulisan makin jelas dilihat", "Tulisan menghilang", "Mata menjadi buta"], "a": 1, "e": "Cahaya yang lebih terang membuat penglihatan lebih jelas (clearer)."}, {"lv": "C5", "vis": "🌄", "q": "Manakah alasan paling tepat mengapa bayangan di pagi hari panjang?", "o": ["Matahari rendah di langit", "Matahari sangat dekat", "Bendanya kecil", "Angin bertiup"], "a": 0, "e": "Saat matahari rendah di langit, bayangan menjadi panjang (long shadow)."}, {"lv": "C5", "vis": "😎", "q": "Seorang anak memakai kacamata hitam di dalam kamar yang gelap.\nApa yang terjadi?", "o": ["Penglihatan makin jelas", "Penglihatan makin sulit", "Cahaya bertambah", "Tidak berpengaruh apa-apa"], "a": 1, "e": "Mengurangi cahaya di tempat yang sudah gelap membuat penglihatan makin sulit."}, {"lv": "C5", "vis": "🪞", "q": "Kesimpulan: benda mengkilap memantulkan cahaya paling baik.\nManakah yang paling cocok untuk melihat bayangan wajah?", "o": ["Kain", "Cermin", "Kertas", "Batu"], "a": 1, "e": "Cermin adalah benda mengkilap yang memantulkan cahaya dengan baik (reflects well)."}, {"lv": "C6", "vis": "🏫", "q": "Kamu ingin membuat ruang kelas lebih terang tanpa menambah lampu.\nRancangan mana yang paling tepat?", "o": ["Menutup semua jendela", "Membuka tirai agar cahaya matahari masuk", "Mematikan semua lampu", "Memasang kain gelap di jendela"], "a": 1, "e": "Membuka tirai memanfaatkan cahaya matahari alami agar kelas lebih terang (natural light)."}, {"lv": "C6", "vis": "🎭", "q": "Kamu membuat pertunjukan bayangan tangan.\nAgar bayangan terlihat paling jelas, apa rancangan terbaik?", "o": ["Lampu redup yang jauh dari dinding", "Lampu terang dekat dinding dengan tangan di antaranya", "Tanpa lampu sama sekali", "Lampu di belakang dinding"], "a": 1, "e": "Lampu terang di depan, tangan di antaranya, dan dinding sebagai layar menghasilkan bayangan paling jelas."}, {"lv": "C6", "vis": "🧪", "q": "Kamu ingin membuktikan bahwa cahaya dapat menembus benda bening.\nPercobaan mana yang paling tepat?", "o": ["Meletakkan batu di depan lampu", "Meletakkan gelas bening berisi air di depan lampu", "Menutup lampu dengan kardus", "Mematikan lampu"], "a": 1, "e": "Gelas bening berisi air membuktikan bahwa cahaya dapat menembus benda bening (transparent)."}, {"lv": "C6", "vis": "🌒", "q": "Kamu merancang cara melindungi mata saat menonton gerhana matahari.\nCara mana yang paling aman?", "o": ["Melihat langsung ke matahari", "Memakai kacamata khusus gerhana", "Memakai kacamata hitam biasa", "Melihat melalui genangan air"], "a": 1, "e": "Kacamata khusus gerhana paling aman untuk melindungi mata (eye safety)."}, {"lv": "C6", "vis": "🌳", "q": "Kamu ingin membuat bayangan pohon di halaman menjadi lebih panjang.\nApa yang bisa kamu lakukan?", "o": ["Menaikkan lampu matahari lebih tinggi", "Menyalakan lampu dari posisi rendah dekat tanah", "Memendekkan pohon", "Menghapus bayangan"], "a": 1, "e": "Sumber cahaya yang rendah menghasilkan bayangan yang lebih panjang (longer shadow)."}, {"lv": "C4", "vis": "☀️", "q": "Pagi hari, Rina membuka tirai kamarnya. Tiba-tiba kamar yang tadinya gelap menjadi terang.\nMengapa hal itu terjadi?", "o": ["Karena cahaya matahari masuk ke dalam kamar", "Karena tirai kamar mengeluarkan cahaya sendiri", "Karena udara di kamar menjadi lebih dingin", "Karena kamar Rina berubah menjadi lebih besar"], "a": 0, "e": "Matahari adalah sumber cahaya utama. Saat tirai dibuka, cahaya matahari (sunlight) masuk dan menerangi kamar."}, {"lv": "C4", "vis": "🔦", "q": "Doni menyalakan lampu senter ke arah dinding. Dinding itu menjadi terang.\nApa yang sebenarnya dikirim senter ke dinding?", "o": ["Panas saja", "Cahaya (light)", "Suara", "Angin"], "a": 1, "e": "Senter adalah sumber cahaya buatan. Ia mengirim cahaya ke dinding sehingga dinding terlihat terang."}, {"lv": "C4", "vis": "🌕", "q": "Pada malam hari, Bulan terlihat bersinar terang di langit.\nMengapa Bulan terlihat terang?", "o": ["Bulan membuat cahayanya sendiri", "Bulan memantulkan cahaya matahari (reflection)", "Bulan terbakar seperti api", "Bulan menyerap cahaya lampu bumi"], "a": 1, "e": "Bulan tidak membuat cahaya sendiri. Bulan memantulkan cahaya matahari sehingga tampak bersinar."}, {"lv": "C4", "vis": "🪞", "q": "Sari mengarahkan cahaya senter ke cermin, lalu cahaya itu memantul ke dinding.\nApa yang dilakukan cermin terhadap cahaya?", "o": ["Menyerap semua cahaya", "Mematikan cahaya", "Memantulkan cahaya (reflect)", "Mengubah cahaya menjadi suara"], "a": 2, "e": "Cermin adalah benda yang sangat baik memantulkan cahaya sehingga cahaya jatuh kembali ke arah lain."}, {"lv": "C4", "vis": "🌑", "q": "Di ruangan yang gelap, Budi tidak bisa melihat wajah temannya.\nApa penyebabnya?", "o": ["Tidak ada cahaya yang masuk ke mata (no light)", "Matanya sedang tertutup", "Temannya tidak punya wajah", "Ruangan itu terlalu berisik"], "a": 0, "e": "Kita dapat melihat suatu benda jika ada cahaya yang masuk ke mata. Di ruang gelap tidak ada cahaya, jadi kita tidak bisa melihat."}, {"lv": "C4", "vis": "💡", "q": "Ayah memasang lampu di ruang tamu yang gelap. Setelah lampu menyala, ruangan menjadi terang.\nKesimpulan apa yang tepat?", "o": ["Ruangan bisa menjadi terang karena ada sumber cahaya (source of light)", "Ruangan menjadi terang karena lampunya berbunyi", "Ruangan menjadi terang karena kursi dipindahkan", "Ruangan tetap gelap walau lampu menyala"], "a": 0, "e": "Sumber cahaya seperti lampu membuat ruangan menjadi terang."}, {"lv": "C4", "vis": "🖐️", "q": "Ani berdiri di bawah sinar matahari dan melihat bayangannya di tanah.\nKapan bayangan Ani muncul?", "o": ["Saat ada cahaya yang terhalang oleh benda (blocked light)", "Saat matahari tidak bersinar sama sekali", "Saat Ani berada di ruang gelap tanpa cahaya", "Saat Ani memakai pakaian berwarna terang"], "a": 0, "e": "Bayangan (shadow) muncul ketika cahaya terhalang oleh benda yang tidak bening (opaque)."}, {"lv": "C4", "vis": "🌞", "q": "Hari ini sangat panas dan matahari bersinar cerah. Ibu menjemur pakaian dan cepat kering.\nApa hubungan matahari dengan kejadian itu?", "o": ["Matahari memberi cahaya dan panas (light and heat)", "Matahari hanya memberi warna pada pakaian", "Matahari memberi suara agar pakaian kering", "Matahari tidak berpengaruh apa-apa"], "a": 0, "e": "Selain cahaya, matahari juga memberi panas. Panas matahari membuat pakaian basah menjadi kering."}, {"lv": "C4", "vis": "🌙", "q": "Setiap pagi matahari terbit dan setiap malam matahari tidak terlihat.\nApa yang terjadi saat matahari tidak terlihat?", "o": ["Bumi tidak berputar lagi", "Terjadi malam hari (night) di bagian bumi itu", "Matahari pindah ke bulan", "Bumi berhenti berputar"], "a": 1, "e": "Bagian bumi yang membelakangi matahari mengalami malam, karena tidak mendapat cahaya matahari."}, {"lv": "C4", "vis": "🪟", "q": "Bu Guru menunjukkan gelas kaca bening dan papan kayu kepada murid.\nApa perbedaan sifat kedua benda itu terhadap cahaya?", "o": ["Kaca meneruskan cahaya, kayu menghalangi cahaya", "Kaca menghalangi cahaya, kayu meneruskan cahaya", "Keduanya sama-sama menghalangi cahaya", "Keduanya sama-sama meneruskan cahaya"], "a": 0, "e": "Kaca bening meneruskan cahaya (transparent), sedangkan kayu menghalangi cahaya (opaque)."}, {"lv": "C4", "vis": "🧪", "q": "Rina ingin tahu benda mana yang bisa membuat bayangan paling gelap di dinding.\nBenda apa yang paling tepat ia pilih?", "o": ["Kertas minyak", "Buku tebal", "Plastik bening", "Gelas kaca jernih"], "a": 1, "e": "Benda tidak bening seperti buku tebal menghalangi cahaya sepenuhnya, sehingga bayangan sangat gelap."}, {"lv": "C4", "vis": "🕯️", "q": "Saat lampu mati, Ayah menyalakan lilin. Ruangan kembali menjadi agak terang.\nApa fungsi lilin saat itu?", "o": ["Menyerap cahaya dari luar", "Menjadi sumber cahaya buatan (artificial light source)", "Menjadi sumber suara", "Menjadi sumber angin"], "a": 1, "e": "Lilin adalah sumber cahaya buatan, karena dibuat oleh manusia; ia menerangi saat tidak ada cahaya lain."}, {"lv": "C4", "vis": "👕", "q": "Bayu memakai kaos putih dan kakaknya memakai kaos hitam saat bermain di bawah matahari.\nBagaimana warna pakaian mempengaruhi panas yang dirasakan?", "o": ["Kaos hitam menyerap panas lebih banyak (absorb heat)", "Kaos putih menyerap panas lebih banyak", "Kedua kaos menyerap panas sama banyak", "Warna pakaian tidak berhubungan dengan panas"], "a": 0, "e": "Warna gelap menyerap panas dan cahaya lebih banyak, sehingga terasa lebih panas."}, {"lv": "C4", "vis": "🏫", "q": "Di kelas, lampu dimatikan saat matahari sudah bersinar terang lewat jendela.\nMengapa Bu Guru melakukan itu?", "o": ["Karena cahaya matahari sudah cukup menerangi kelas", "Karena lampu akan meletus", "Karena cahaya matahari membuat kelas gelap", "Karena lampu tidak punya sakelar"], "a": 0, "e": "Cahaya matahari masuk melalui jendela dan cukup menerangi kelas, sehingga lampu tidak perlu dinyalakan."}, {"lv": "C4", "vis": "🪞", "q": "Dina bercermin sebelum berangkat sekolah. Ia melihat wajahnya jelas di cermin.\nApa yang memungkinkan hal itu terjadi?", "o": ["Cermin mengeluarkan cahaya sendiri", "Cahaya dari Dina dipantulkan cermin ke matanya (reflected light)", "Cermin menyerap semua cahaya", "Cermin berubah menjadi wajah Dina"], "a": 1, "e": "Cahaya yang mengenai Dina dipantulkan ke cermin, lalu cermin memantulkannya ke mata Dina, sehingga ia melihat wajahnya."}, {"lv": "C4", "vis": "🔍", "q": "Ayah memakai kacamata bening. Andi memakai kacamata hitam tebal.\nKacamat siapa yang tetap terlihat terang saat memandang matahari?", "o": ["Kacamata bening, karena mudah dilewati cahaya", "Kacamata hitam tebal, karena semua cahaya lewat", "Keduanya sama-sama gelap", "Kacamata bening tidak dilewati cahaya"], "a": 0, "e": "Kacamata bening adalah benda bening yang mudah dilewati cahaya (transparent), sehingga pemandangan terlihat terang. (Kacamata hitam tebal justru lebih aman untuk melihat matahari.)"}, {"lv": "C4", "vis": "🪴", "q": "Tanaman di pot dekat jendela tumbuh subur dan menghadap ke arah matahari.\nMengapa tanaman itu tumbuh ke arah jendela?", "o": ["Karena tanaman mencari suara dari luar", "Karena tanaman membutuhkan cahaya matahari (sunlight)", "Karena tanaman takut pada pot", "Karena tanaman mencari angin dari jendela"], "a": 1, "e": "Tanaman memerlukan cahaya matahari sebagai sumber energi untuk tumbuh; karena itu ia tumbuh mengarah ke cahaya."}, {"lv": "C4", "vis": "🌤️", "q": "Ketika langit tertutup awan tebal, siang hari terasa tidak terlalu terang.\nMengapa hal itu terjadi?", "o": ["Matahari mati saat ada awan", "Awan menghalangi sebagian cahaya matahari (blocks sunlight)", "Awan berubah menjadi lampu", "Bumi berhenti menerima cahaya"], "a": 1, "e": "Awan tebal menghalangi sebagian cahaya matahari, sehingga siang terasa kurang terang."}, {"lv": "C4", "vis": "🔆", "q": "Pada siang hari yang cerah, Andi berdiri di lapangan.\nBagaimana bayangan Andi dibandingkan pagi hari?", "o": ["Bayangannya lebih panjang", "Bayangannya lebih pendek dan ada di bawah tubuhnya", "Bayangannya tidak ada", "Bayangannya berwarna putih"], "a": 1, "e": "Saat matahari tinggi di langit (siang), bayangan lebih pendek karena cahaya datang hampir dari atas kepala."}, {"lv": "C4", "vis": "⚫", "q": "Bayangan kursi terlihat sangat gelap dan tajam di dinding saat lampu menyala dekat kursi.\nApa yang membuat bayangan itu gelap?", "o": ["Karena kursi menghalangi cahaya (blocks light)", "Karena dinding menyerap semua cahaya", "Karena kursi berwarna terang", "Karena lampu mengeluarkan suara"], "a": 0, "e": "Kursi adalah benda tidak bening yang menghalangi cahaya, sehingga daerah di belakangnya gelap dan membentuk bayangan."}, {"lv": "C4", "vis": "🍶", "q": "Ibu ingin anaknya bisa melihat buah di dalam kotak tanpa harus membuka kotak.\nBahan apa yang paling cocok untuk membuat kotak itu?", "o": ["Kayu papan tebal", "Plastik bening", "Kardus berwarna", "Logam tebal"], "a": 1, "e": "Plastik bening bersifat bening (transparent), sehingga cahaya lewat dan isi kotak dapat dilihat dari luar."}, {"lv": "C4", "vis": "🛏️", "q": "Kakak tidak bisa tidur karena kamarnya gelap sama sekali.\nApa yang bisa dilakukan agar kamar tidak terlalu gelap?", "o": ["Menutup semua jendela dengan kardus", "Menyalakan lampu tidur kecil (night lamp)", "Memadamkan semua lampu", "Menutup pintu rapat-rapat"], "a": 1, "e": "Menyalakan lampu kecil sebagai sumber cahaya membuat kamar tidak terlalu gelap."}, {"lv": "C4", "vis": "🌈", "q": "Pelangi muncul di langit setelah hujan ketika matahari bersinar.\nMengapa pelangi muncul?", "o": ["Cahaya matahari mengenai titik air hujan dan terurai (rainbow)", "Air hujan berubah menjadi cat warna", "Matahari memantul dari lampu", "Awan mengeluarkan warna"], "a": 0, "e": "Cahaya matahari yang menembus titik air hujan terurai menjadi warna-warni, sehingga tampak pelangi."}, {"lv": "C4", "vis": "🧴", "q": "Di kelas, Bu Guru meminta murid memilih benda tembus pandang untuk percobaan cahaya.\nBenda mana yang paling tepat dipilih?", "o": ["Air jernih di gelas bening", "Susu kental manis", "Kayu papan", "Batu besar"], "a": 0, "e": "Air jernih dalam gelas bening bersifat tembus pandang (transparent), sehingga cahaya dapat melaluinya."}, {"lv": "C4", "vis": "🏠", "q": "Rumah nenek di desa memiliki banyak jendela besar dan atap kaca di bagian tengah.\nApa manfaatnya bagi rumah itu?", "o": ["Rumah menjadi lebih terang pada siang hari (natural lighting)", "Rumah menjadi lebih gelap", "Rumah menjadi lebih besar", "Rumah menjadi lebih dingin saja"], "a": 0, "e": "Jendela dan atap kaca bening meneruskan cahaya matahari, sehingga rumah terang tanpa banyak lampu pada siang hari."}, {"lv": "C4", "vis": "📦", "q": "Doni membandingkan bayangan dua benda: buku tebal dan kertas minyak.\nBayangan benda mana yang lebih gelap?", "o": ["Buku tebal, karena menghalangi cahaya sepenuhnya", "Kertas minyak, karena meneruskan sebagian cahaya", "Keduanya sama gelap", "Keduanya tidak punya bayangan"], "a": 0, "e": "Buku tebal adalah benda tidak bening yang menghalangi cahaya sepenuhnya, sehingga bayangannya lebih gelap."}, {"lv": "C4", "vis": "🕶️", "q": "Saat matahari sangat terik, Ayah memakai topi lebar saat bekerja di sawah.\nApa manfaat topi itu?", "o": ["Menghalangi cahaya dan panas matahari (blocks sunlight)", "Menyerap semua cahaya matahari", "Membuat sawah menjadi terang", "Mengubah cahaya menjadi suara"], "a": 0, "e": "Topi lebar menghalangi cahaya matahari langsung, sehingga kepala dan wajah terlindung dari panas."}, {"lv": "C5", "vis": "❄️", "q": "Edo meletakkan dua kotak es di bawah sinar matahari. Kotak A ditutup kain putih, kotak B ditutup kain hitam.\nKotak mana yang esnya lebih cepat mencair?", "o": ["Kotak A, karena kain putih menyerap lebih banyak panas", "Kotak B, karena kain hitam menyerap lebih banyak panas (absorbs heat)", "Keduanya mencair bersamaan", "Tidak ada yang mencair"], "a": 1, "e": "Kain hitam menyerap panas matahari lebih banyak daripada kain putih, sehingga es di kotak B lebih cepat mencair."}, {"lv": "C5", "vis": "🪞", "q": "Nina ingin melihat bagian belakang kepalanya tanpa memutar tubuh.\nAlat apa yang paling tepat dia gunakan?", "o": ["Sebuah cermin yang dipantulkan ke kaca lain (two mirrors)", "Sebuah lampu senter", "Sebuah kertas putih", "Sebuah kain gelap"], "a": 0, "e": "Dua cermin memantulkan cahaya satu ke yang lain, sehingga Nina dapat melihat bagian belakang kepalanya."}, {"lv": "C5", "vis": "🏮", "q": "Saat listrik padam, Ibu ingin ruangan tetap terang dengan satu lilin.\nCara apa yang paling tepat dilakukan?", "o": ["Meletakkan lilin di dekat cermin agar cahaya memantul ke seluruh ruangan", "Menutup lilin dengan kain tebal", "Memindahkan lilin ke luar rumah", "Meletakkan lilin di dalam kotak tertutup"], "a": 0, "e": "Cermin memantulkan cahaya lilin ke arah lain, sehingga ruangan menjadi lebih terang walau hanya ada satu lilin."}, {"lv": "C5", "vis": "⏰", "q": "Pada pagi hari, bayangan tiang bendera cukup panjang. Saat tengah hari, bayangannya menjadi pendek.\nApa yang menyebabkan perbedaan itu?", "o": ["Karena arah datangnya cahaya matahari berubah (angle of light)", "Karena tiang bendera menjadi lebih pendek", "Karena matahari mengubah warna tiang", "Karena angin menekan tiang"], "a": 0, "e": "Semakin tinggi posisi matahari, semakin pendek bayangan. Arah dan sudut cahaya mempengaruhi bentuk bayangan."}, {"lv": "C5", "vis": "🔤", "q": "Kamu ingin membuat huruf besar-besar pada layar di dinding untuk pertunjukan boneka.\nBagaimana cara menggunakan sumber cahaya untuk memperbesar bayangan?", "o": ["Dekatkan boneka ke cahaya dan jauhkan dari dinding", "Dekatkan boneka ke cahaya dan dekatkan ke dinding", "Jauhkan boneka dari cahaya", "Matikan semua cahaya"], "a": 0, "e": "Bayangan menjadi lebih besar jika benda lebih dekat ke sumber cahaya dan lebih jauh dari layar/dinding."}, {"lv": "C5", "vis": "🏠", "q": "Sebuah kamar memiliki jendela yang menghadap ke dinding tetangga sehingga tetap gelap.\nCara apa yang paling tepat membuat kamar itu terang pada siang hari?", "o": ["Memasang atap kaca yang meneruskan cahaya matahari (skylight)", "Mengecat dinding menjadi hitam", "Menutup jendela dengan kayu", "Memadamkan semua lampu"], "a": 0, "e": "Atap kaca bening dapat meneruskan cahaya matahari masuk, sehingga kamar menjadi terang pada siang hari."}, {"lv": "C5", "vis": "🕯️", "q": "Ardi menutup lilin dengan gelas bening. Cahaya lilin masih terlihat dari luar.\nMengapa cahaya masih terlihat?", "o": ["Karena gelas bening meneruskan cahaya (transparent)", "Karena gelas menyerap cahaya", "Karena gelas berubah menjadi lilin", "Karena gelas memantulkan suara"], "a": 0, "e": "Gelas bening bersifat bening, sehingga cahaya lilin dapat melewatinya dan tetap terlihat dari luar."}, {"lv": "C5", "vis": "🌑", "q": "Pada gerhana matahari, sinar matahari tertutup oleh bulan dan siang hari menjadi gelap.\nApa yang terjadi sebenarnya?", "o": ["Matahari berhenti bersinar", "Bulan menghalangi cahaya matahari ke bumi (blocked sunlight)", "Bumi berhenti berputar", "Bulan mengeluarkan cahaya"], "a": 1, "e": "Gerhana matahari terjadi saat bulan berada di antara bumi dan matahari, sehingga cahaya matahari terhalang."}, {"lv": "C5", "vis": "🌗", "q": "Mengapa bagian bumi yang kita tinggali mengalami siang dan malam secara bergantian?", "o": ["Karena bumi berputar (rotates), sehingga bergantian menghadap matahari", "Karena matahari mati dan menyala kembali", "Karena bulan menutup matahari setiap malam", "Karena awan menutup matahari"], "a": 0, "e": "Bumi berputar pada porosnya. Bagian yang menghadap matahari mengalami siang, bagian yang membelakangi mengalami malam."}, {"lv": "C5", "vis": "🔬", "q": "Dua benda diletakkan di depan lampu: gelas kaca bening dan papan kayu. Bayangan keduanya dibandingkan.\nHasil apa yang paling mungkin didapat?", "o": ["Papan kayu memberi bayangan gelap, kaca bening memberi bayangan terang", "Kaca bening memberi bayangan gelap, papan kayu memberi bayangan terang", "Keduanya memberi bayangan sama gelap", "Keduanya tidak memberi bayangan"], "a": 0, "e": "Kayu menghalangi cahaya sepenuhnya sehingga bayangannya gelap; kaca bening meneruskan cahaya sehingga bayangannya terang."}, {"lv": "C5", "vis": "🪟", "q": "Bu Guru menempel plastik buram (tembus cahaya, tidak bening) pada jendela kelas.\nApa yang akan terjadi pada cahaya yang masuk?", "o": ["Cahaya masuk sebagian, ruangan menjadi sedikit remang (translucent)", "Cahaya masuk seluruhnya, ruangan sangat terang", "Cahaya tidak masuk sama sekali, ruangan gelap", "Cahaya berubah menjadi suara"], "a": 0, "e": "Benda buram (translucent) hanya meneruskan sebagian cahaya, sehingga ruangan menjadi remang-remang."}, {"lv": "C5", "vis": "☂️", "q": "Ibu menjemur pakaian di bawah sinar matahari. Setelah beberapa jam, pakaian basah menjadi kering.\nApa penyebab utamanya?", "o": ["Panas matahari menguapkan air pada pakaian (evaporation)", "Angin meniup air ke langit", "Pakaian menyerap cahaya dan menjadi kering", "Pakaian berubah warna menjadi putih"], "a": 0, "e": "Panas matahari memanaskan air pada pakaian, sehingga air menguap dan pakaian menjadi kering."}, {"lv": "C5", "vis": "🔭", "q": "Pada suatu percobaan, cahaya senter diarahkan ke tiga benda: kayu, kertas, dan kaca bening.\nBenda mana yang paling menghalangi cahaya?", "o": ["Kayu, karena tidak meneruskan cahaya", "Kertas, karena meneruskan seluruh cahaya", "Kaca bening, karena gelap", "Ketiganya sama"], "a": 0, "e": "Kayu adalah benda tidak bening yang paling menghalangi cahaya, lebih dari kertas dan kaca bening."}, {"lv": "C5", "vis": "🏫", "q": "Bu Guru meminta siswa membuat ruangan kelas lebih terang tanpa menambah lampu.\nUsulan mana yang paling tepat?", "o": ["Mengecat dinding dengan warna terang dan menambah jendela", "Menggantung kain gelap di dinding", "Menutup semua jendela dengan kardus", "Mengecat dinding dengan warna hitam"], "a": 0, "e": "Dinding berwarna terang memantulkan lebih banyak cahaya, dan jendela menambah cahaya masuk, sehingga kelas lebih terang."}, {"lv": "C5", "vis": "🧊", "q": "Dua gelas berisi air sama banyak. Gelas P dibungkus plastik hitam, gelas Q dibungkus plastik putih. Keduanya diletakkan di terik matahari.\nHasil apa yang paling mungkin?", "o": ["Air gelas P lebih hangat karena plastik hitam menyerap panas lebih banyak", "Air gelas P lebih dingin karena plastik hitam memantulkan panas", "Air kedua gelas sama dingin", "Air gelas Q lebih cepat panas"], "a": 0, "e": "Warna hitam menyerap panas lebih banyak daripada warna putih, sehingga air di gelas P lebih hangat."}, {"lv": "C5", "vis": "🌓", "q": "Rudi melihat bahwa bayangan pohon di halaman berubah arah: pagi ke satu arah, sore ke arah lain.\nApa kesimpulan yang tepat?", "o": ["Arah bayangan mengikuti arah datangnya cahaya matahari (direction of light)", "Pohon berpindah tempat", "Bayangan bergerak karena angin", "Arah bayangan tidak dipengaruhi cahaya"], "a": 0, "e": "Bayangan selalu berada di sisi berlawanan dari sumber cahaya, sehingga arahnya berubah saat posisi matahari berubah."}, {"lv": "C5", "vis": "🧵", "q": "Seorang penjahit membutuhkan cahaya banyak untuk memasukkan benang ke jarum, tetapi ia tidak ingin lampunya terlalu panas.\nPilihan apa yang paling tepat?", "o": ["Lampu LED yang terang dan tidak terlalu panas", "Lilin besar", "Lampu yang ditutup kain", "Tidak memakai pencahayaan"], "a": 0, "e": "Lampu LED memberi cahaya terang dengan panas yang lebih sedikit, sehingga cocok untuk pekerjaan yang memerlukan cahaya banyak."}, {"lv": "C5", "vis": "🔘", "q": "Mengapa bulan terlihat terang pada malam hari, padahal bulan bukan sumber cahaya?", "o": ["Karena bulan memantulkan cahaya matahari (reflects sunlight)", "Karena bulan menyala seperti lampu", "Karena bulan terbuat dari kaca", "Karena bulan menyerap cahaya bumi"], "a": 0, "e": "Bulan memantulkan cahaya matahari yang jatuh padanya, sehingga tampak terang dari bumi."}, {"lv": "C6", "vis": "🧪", "q": "Ani ingin menguji apakah bayangan benda berubah ukuran saat jaraknya berubah. Ia menyinari mainan dengan lampu dan mengukur bayangan di dinding.\nVariabel apa yang sebaiknya ia ubah (diubah-ubah) dalam percobaan itu?", "o": ["Jarak mainan dari lampu dan dari dinding", "Warna dinding ruangan", "Nama mainan yang dipakai", "Warna lampu ruangan"], "a": 0, "e": "Dalam percobaan ini, variabel yang diubah adalah jarak mainan terhadap lampu dan dinding, karena itulah yang dapat mempengaruhi ukuran bayangan."}, {"lv": "C6", "vis": "🧫", "q": "Rio ingin tahu benda mana yang paling menghalangi cahaya di antara kertas, kayu, dan kaca bening. Ia menyinari ketiga benda itu satu per satu dan mencatat terang/gelapnya bayangan.\nApa yang harus Rio jaga tetap sama (dikontrol)?", "o": ["Jarak benda ke lampu dan ke dinding, serta jenis lampu", "Warna benda dan bentuk benda", "Ukuran benda dan rasanya", "Nama teman yang menonton"], "a": 0, "e": "Agar hasilnya adil, hanya sifat benda yang boleh berbeda. Jarak ke lampu, jarak ke dinding, dan jenis lampu harus tetap sama."}, {"lv": "C6", "vis": "🌞", "q": "Dua kelompok menguji warna kain mana yang menyerap panas lebih cepat. Kelompok A meletakkan kain hitam di bawah matahari; Kelompok B meletakkan kain putih di bawah pohon yang teduh.\nMengapa hasil percobaan itu kurang dapat dipercaya?", "o": ["Karena tempat percobaan berbeda, sehingga banyak hal lain yang mempengaruhi panas", "Karena kain terlalu besar", "Karena warna kain tidak berpengaruh", "Karena percobaan terlalu cepat"], "a": 0, "e": "Percobaan harus dilakukan di tempat dan kondisi yang sama. Jika berbeda tempat (matahari vs teduh), hasilnya tidak dapat dibandingkan dengan adil."}, {"lv": "C6", "vis": "🧴", "q": "Seorang siswa ingin membuat ruangan gelap gulita untuk menguji apakah tumbuhan tetap tumbuh dengan cahaya sedikit.\nLangkah apa yang paling tepat pertama kali ia lakukan?", "o": ["Menyiapkan dua tempat: satu terang dan satu gelap, lalu mencatat hasil tiap hari", "Menyiram tumbuhan dengan air panas", "Meletakkan semua tumbuhan di tempat terang", "Membuang tumbuhan yang tidak tumbuh"], "a": 0, "e": "Percobaan yang baik membandingkan dua kondisi berbeda (terang dan gelap) sambil mencatat hasil setiap hari."}, {"lv": "C6", "vis": "📏", "q": "Kamu diminta menyelidiki pada jam berapa bayangan tongkat paling pendek di halaman sekolah.\nRancangan percobaan mana yang paling tepat?", "o": ["Menancapkan tongkat, mengukur panjang bayangannya setiap jam dari pagi sampai sore, lalu mencatatnya", "Mengukur bayangan sekali pada pagi hari", "Menanyakan kepada teman saja", "Mengubah posisi tongkat setiap kali mengukur"], "a": 0, "e": "Untuk menemukan bayangan terpendek, panjang bayangan harus diukur berkali-kali pada waktu berbeda sepanjang hari, sedangkan posisi tongkat tetap."}, {"lv": "C4", "vis": "🌱", "q": "Rina menaruh pot tanaman kacang hijau di dalam lemari yang gelap selama satu minggu. Tanaman itu tumbuh tinggi, tetapi daunnya berwarna pucat kekuningan. Apa penyebab daun tanaman itu pucat?", "o": ["Kekurangan tanah", "Kekurangan cahaya matahari", "Kekurangan air", "Kelebihan pupuk"], "a": 1, "e": "Cahaya matahari diperlukan daun untuk membuat makanan (fotosintesis). Tanpa cahaya, daun tidak dapat membentuk zat hijau daun (klorofil) sehingga tampak pucat kekuningan."}, {"lv": "C4", "vis": "🥕", "q": "Akar wortel tebal dan berisi cadangan makanan, sedangkan akar pohon mangga kuat dan bercabang banyak. Fungsi akar yang sama pada kedua tanaman tersebut adalah ....", "o": ["Membuat makanan dengan bantuan cahaya", "Menarik perhatian serangga penyerbuk", "Menyimpan oksigen untuk daun", "Menyerap air dan zat hara dari dalam tanah"], "a": 3, "e": "Semua tumbuhan memiliki akar yang berfungsi menyerap air dan zat hara dari tanah. Bentuk akar dapat berbeda karena kegunaan tambahannya."}, {"lv": "C4", "vis": "🌵", "q": "Daun lidah buaya tebal dan berisi air, sedangkan daun padi tipis dan lebar. Berdasarkan ciri daunnya, tempat hidup yang paling cocok untuk lidah buaya adalah ....", "o": ["Tempat kering dan panas seperti gurun", "Sawah yang selalu tergenang air", "Hutan hujan yang sangat lembap", "Dasar kolam yang gelap"], "a": 0, "e": "Daun tebal berisi air adalah ciri tumbuhan yang hidup di tempat kering dan panas. Cadangan air membantunya bertahan saat kekeringan."}, {"lv": "C4", "vis": "🍃", "q": "Bu Sari memotong semua daun pada tanaman hias kesayangannya. Beberapa minggu kemudian tanaman itu mati. Mengapa hal itu terjadi?", "o": ["Bunga tidak dapat mekar lagi", "Akar tidak dapat menyerap air dari tanah", "Tanaman tidak dapat membuat makanan tanpa daun", "Batang tidak dapat berdiri tegak lagi"], "a": 2, "e": "Daun adalah tempat tumbuhan membuat makanan (fotosintesis). Jika semua daun hilang, tumbuhan tidak dapat membuat makanan sehingga akhirnya mati."}, {"lv": "C4", "vis": "🌸", "q": "Bunga memiliki mahkota berwarna cerah dan berbau harum. Apa fungsi bagian bunga tersebut bagi tumbuhan?", "o": ["Menopang daun agar tidak jatuh", "Menarik serangga agar membantu penyerbukan", "Menyerap air dari udara sekitar", "Menghasilkan biji tanpa penyerbukan"], "a": 1, "e": "Warna cerah dan bau harum menarik serangga penyerbuk. Serangga itu membantu penyerbukan sehingga bunga dapat berkembang menjadi buah dan biji."}, {"lv": "C4", "vis": "📦", "q": "Andi menutup satu pot tanaman dengan kardus, sedangkan pot lain dibiarkan terkena sinar matahari. Kedua pot disiram setiap hari. Setelah lima hari, tanaman di dalam kardus tampak kurus dan pucat. Kesimpulan yang tepat dari percobaan itu adalah ....", "o": ["Pupuk membuat tumbuhan pucat", "Kardus membuat tanah menjadi kering", "Air tidak dibutuhkan tumbuhan", "Cahaya matahari diperlukan agar tumbuhan tumbuh sehat"], "a": 3, "e": "Satu-satunya perbedaan percobaan adalah ada atau tidaknya cahaya matahari. Tanaman yang gelap menjadi kurus dan pucat, jadi cahaya matahari diperlukan agar tumbuhan tumbuh sehat."}, {"lv": "C4", "vis": "🏠", "q": "Sebuah tanaman diletakkan di kamar tertutup yang gelap. Tanaman itu tetap disiram dan diberi pupuk setiap minggu, tetapi tetap tidak tumbuh subur. Hal ini menunjukkan bahwa ....", "o": ["Cahaya matahari termasuk kebutuhan penting tumbuhan", "Pupuk justru merusak tanaman", "Tanaman di dalam ruangan selalu mati", "Air dan pupuk tidak diperlukan tumbuhan"], "a": 0, "e": "Air dan pupuk sudah diberikan, tetapi tumbuhan tetap tidak subur karena tidak mendapat cahaya matahari. Jadi cahaya matahari termasuk kebutuhan penting tumbuhan."}, {"lv": "C4", "vis": "🫘", "q": "Biji kacang hijau A diletakkan di atas kapas basah, sedangkan biji B diletakkan di atas kapas kering. Setelah tiga hari, biji A berkecambah dan biji B tidak. Faktor yang memengaruhi percobaan itu adalah ....", "o": ["Tanah", "Cahaya matahari", "Udara", "Air"], "a": 3, "e": "Perbedaan percobaan hanya pada kapas basah dan kapas kering, yaitu air. Biji memerlukan air untuk berkecambah."}, {"lv": "C4", "vis": "🎋", "q": "Pak Tani mengikat batang pohon muda ke sebuah tiang bambu. Apa manfaat tindakan tersebut?", "o": ["Agar akar tumbuh lebih cepat", "Agar daun berubah menjadi bunga", "Agar batang tumbuh tegak dan tidak mudah roboh", "Agar tanaman tidak perlu disiram"], "a": 2, "e": "Batang pohon muda masih lentur sehingga mudah bengkok atau roboh. Tiang penopang membuat batang tumbuh tegak dan kuat."}, {"lv": "C4", "vis": "🦋", "q": "Daur hidup kupu-kupu adalah telur - ulat - kepompong - kupu-kupu dewasa. Jika semua ulat di kebun habis dimakan burung, apa yang akan terjadi?", "o": ["Telur kupu-kupu bertambah banyak", "Kupu-kupu dewasa bertelur di udara", "Kepompong berubah menjadi ulat baru", "Kepompong dan kupu-kupu baru tidak terbentuk"], "a": 3, "e": "Ulat adalah tahap sebelum kepompong. Tanpa ulat, tidak ada kepompong sehingga kupu-kupu baru juga tidak terbentuk."}, {"lv": "C4", "vis": "🥭", "q": "Pada pohon mangga, bunga akan berkembang menjadi buah yang berisi biji. Jika semua bunga mangga rontok sebelum menjadi buah, apa yang akan terjadi?", "o": ["Batang pohon mangga tumbuh lebih cepat", "Pohon mangga tidak menghasilkan buah dan biji baru", "Daun pohon mangga berubah menjadi buah", "Akar pohon mangga berhenti menyerap air"], "a": 1, "e": "Buah dan biji berasal dari bunga yang telah diserbuki. Jika semua bunga rontok, pohon tidak menghasilkan buah dan biji baru."}, {"lv": "C4", "vis": "🐸", "q": "Kecebong hidup di air dan bernapas dengan insang, sedangkan katak dewasa dapat hidup di darat dan di air serta bernapas dengan paru-paru dan kulit. Perbedaan itu menunjukkan bahwa ....", "o": ["Kecebong tidak memerlukan makanan", "Kecebong dan katak adalah dua jenis hewan berbeda", "Katak dewasa tidak memerlukan air", "Katak mengalami perubahan bentuk dan cara hidup saat dewasa"], "a": 3, "e": "Katak mengalami metamorfosis: bentuk dan cara hidupnya berubah dari kecebong menjadi katak dewasa."}, {"lv": "C4", "vis": "🐄", "q": "Sapi, kambing, dan kerbau dikelompokkan ke dalam satu golongan hewan karena ....", "o": ["Tidak memerlukan makanan", "Memakan tumbuhan dan daging (omnivora)", "Memakan tumbuhan (herbivora)", "Memakan daging (karnivora)"], "a": 2, "e": "Ketiga hewan itu makan rumput dan tumbuhan lain, jadi termasuk herbivora."}, {"lv": "C4", "vis": "🦁", "q": "Kucing dan singa memiliki gigi taring yang tajam dan kuat. Berdasarkan bentuk giginya, kedua hewan itu termasuk pemakan ....", "o": ["Tumbuhan (herbivora)", "Buah-buahan saja", "Daging (karnivora)", "Segala makanan (omnivora)"], "a": 2, "e": "Gigi taring yang tajam digunakan untuk mencabik daging. Gigi seperti itu adalah ciri hewan karnivora."}, {"lv": "C4", "vis": "🐔", "q": "Ayam memakan biji-bijian, daun muda, dan cacing. Berdasarkan jenis makanannya, ayam termasuk hewan ....", "o": ["Pemakan daging saja (karnivora)", "Tidak memakan apa pun", "Pemakan segala (omnivora)", "Pemakan tumbuhan saja (herbivora)"], "a": 2, "e": "Ayam memakan tumbuhan dan juga hewan kecil seperti cacing, jadi termasuk omnivora atau pemakan segala."}, {"lv": "C4", "vis": "🐟", "q": "Ikan bernapas dengan insang dan bergerak menggunakan sirip. Ciri tubuh tersebut menunjukkan bahwa ikan hidup di ....", "o": ["Air", "Tanah yang kering", "Pepohonan", "Udara"], "a": 0, "e": "Insang untuk mengambil oksigen terlarut dan sirip untuk berenang adalah ciri hewan yang hidup di air."}, {"lv": "C4", "vis": "🐫", "q": "Unta memiliki punuk berisi cadangan lemak dan tahan tidak minum dalam waktu lama. Ciri tersebut sesuai untuk hidup di ....", "o": ["Padang pasir yang kering", "Laut yang dalam", "Sungai yang berarus deras", "Hutan yang lembap"], "a": 0, "e": "Cadangan lemak pada punuk membantu unta bertahan tanpa makan dan minum lama, sesuai dengan daerah gurun atau padang pasir yang kering."}, {"lv": "C4", "vis": "🐐", "q": "Anak kambing menyusu kepada induknya sampai cukup besar. Hewan yang menyusui anaknya termasuk kelompok ....", "o": ["Serangga", "Burung", "Mamalia", "Ikan"], "a": 2, "e": "Hewan yang menyusui anaknya disebut mamalia. Kambing, sapi, dan kucing termasuk mamalia."}, {"lv": "C4", "vis": "🥚", "q": "Ayam mengerami telurnya sampai menetas, sedangkan sapi melahirkan anaknya. Perbedaan cara berkembang biak kedua hewan itu adalah ....", "o": ["Keduanya melahirkan", "Ayam bertelur (ovipar), sapi melahirkan (vivipar)", "Keduanya bertelur", "Ayam melahirkan, sapi bertelur"], "a": 1, "e": "Hewan yang berkembang biak dengan bertelur disebut ovipar, sedangkan yang melahirkan anak disebut vivipar."}, {"lv": "C4", "vis": "🥀", "q": "Tanaman di teras rumah menjadi layu karena lupa disiram selama empat hari. Setelah disiram, tanaman itu kembali segar. Hal ini menunjukkan bahwa ....", "o": ["Air tidak berpengaruh bagi tumbuhan", "Tumbuhan dapat hidup tanpa air", "Layu adalah tanda tumbuhan mati", "Tumbuhan termasuk makhluk hidup yang memerlukan air"], "a": 3, "e": "Tanaman layu saat kekurangan air dan segar kembali setelah disiram. Jadi tumbuhan adalah makhluk hidup yang memerlukan air."}, {"lv": "C4", "vis": "🪨", "q": "Sebuah batu diletakkan di atas tanah basah selama satu bulan, tetapi batu itu tidak berubah. Biji kacang hijau di sebelahnya justru tumbuh menjadi tanaman kecil. Perbedaan itu terjadi karena ....", "o": ["Biji dapat tumbuh, sedangkan batu tidak dapat tumbuh", "Batu bernapas, biji tidak", "Batu memerlukan makanan, biji tidak", "Biji tidak memerlukan air, batu memerlukan air"], "a": 0, "e": "Biji adalah makhluk hidup yang dapat tumbuh, sedangkan batu adalah benda mati yang tidak dapat tumbuh walau berada di tempat lembap."}, {"lv": "C4", "vis": "🪑", "q": "Meja, sepeda, dan batu tidak memerlukan makanan, tidak bernapas, dan tidak tumbuh besar. Hal itu menunjukkan bahwa benda-benda tersebut ....", "o": ["Termasuk makhluk hidup", "Termasuk benda mati", "Memerlukan cahaya matahari", "Dapat berkembang biak"], "a": 1, "e": "Tidak makan, tidak bernapas, dan tidak tumbuh adalah ciri benda mati."}, {"lv": "C4", "vis": "🌾", "q": "Rumput liar yang tumbuh di sekitar tanaman cabai dicabut oleh Pak Budi. Apa alasan utama tindakan tersebut?", "o": ["Agar akar cabai tidak tumbuh", "Agar tanah menjadi lebih keras", "Agar tanaman cabai tidak perlu disiram", "Agar rumput liar tidak berebut air, zat hara, dan cahaya"], "a": 3, "e": "Rumput liar menyerap air dan zat hara serta menutupi cahaya. Mencabutnya membuat tanaman cabai mendapat air, zat hara, dan cahaya yang cukup."}, {"lv": "C4", "vis": "🐠", "q": "Ikan hias di akuarium mati setelah airnya tidak diganti selama dua minggu. Penyebab yang paling mungkin adalah ....", "o": ["Ikan terlalu banyak bergerak", "Air menjadi kotor dan oksigen di dalamnya berkurang", "Suhu air menjadi lebih dingin", "Ikan kekurangan cahaya matahari"], "a": 1, "e": "Air akuarium yang lama tidak diganti menjadi kotor dan oksigen berkurang sehingga ikan sulit bernapas lalu mati."}, {"lv": "C4", "vis": "🌾", "q": "Di sawah terdapat rantai makanan: padi - tikus - ular. Jika petani memburu habis semua ular di sawah itu, apa yang paling mungkin terjadi?", "o": ["Jumlah tikus berkurang drastis", "Tikus berkembang pesat sehingga banyak padi rusak", "Padi tumbuh makin subur", "Padi berubah menjadi makanan ular"], "a": 1, "e": "Ular adalah pemangsa tikus. Jika ular habis, tikus tidak ada pemangsa sehingga berkembang pesat dan banyak padi menjadi rusak."}, {"lv": "C4", "vis": "🌳", "q": "Dalam rantai makanan di kebun, tumbuhan hijau selalu berada pada urutan pertama. Peran tumbuhan hijau dalam rantai makanan adalah sebagai ....", "o": ["Pemangsa, yaitu pemakan hewan kecil", "Konsumen, yaitu pemakan hewan lain", "Pengurai, yaitu pembusuk sisa hewan", "Produsen, yaitu sumber makanan bagi hewan"], "a": 3, "e": "Tumbuhan hijau membuat makanannya sendiri dan menjadi sumber makanan pertama bagi hewan, sehingga disebut produsen."}, {"lv": "C4", "vis": "🐛", "q": "Perhatikan rantai makanan berikut: daun - ulat - burung - elang. Jika populasi ulat menurun tajam karena disemprot insektisida, hewan yang paling cepat berkurang jumlahnya adalah ....", "o": ["Burung", "Elang", "Cacing tanah", "Daun"], "a": 0, "e": "Burung memakan ulat secara langsung. Jika ulat berkurang, burung paling cepat kekurangan makanan dan jumlahnya berkurang."}, {"lv": "C5", "vis": "💧", "q": "Adi menyiram tanamannya satu kali sehari secukupnya. Beni menyiram tanamannya lima kali sehari sampai tanah tergenang. Cara siapa yang lebih baik dan mengapa?", "o": ["Adi, karena air yang berlebihan dapat merusak akar", "Beni, karena tanaman butuh air sebanyak mungkin", "Adi, karena tanaman tidak memerlukan air", "Beni, karena tanah basah membuat tanaman cepat berbunga"], "a": 0, "e": "Air secukupnya sudah cukup bagi tanaman. Air berlebihan membuat akar sulit bernapas sehingga akar dapat membusuk."}, {"lv": "C5", "vis": "🐰", "q": "Manakah cara yang paling tepat merawat kelinci peliharaan di rumah?", "o": ["Membiarkan kandang kotor agar kelinci hangat", "Memberi makan sebanyak mungkin sekali seminggu", "Memandikan kelinci setiap jam dengan air dingin", "Memberi makan dan minum teratur serta membersihkan kandang setiap hari"], "a": 3, "e": "Hewan peliharaan perlu makan dan minum teratur serta kandang yang bersih agar sehat dan tidak mudah sakit."}, {"lv": "C5", "vis": "🍅", "q": "Dua tanaman tomat mendapat air yang sama, tetapi tanaman P diletakkan di dekat jendela dan tanaman Q diletakkan di dalam lemari. Setelah satu minggu, tanaman P lebih hijau dan subur. Kesimpulan yang paling tepat adalah ....", "o": ["Air tidak penting bagi tanaman tomat", "Cahaya matahari membantu tanaman tumbuh subur", "Tanaman Q tidak memerlukan tanah", "Tanaman P kebanyakan air"], "a": 1, "e": "Air dan jenis tanaman sama, yang berbeda hanya cahaya. Tanaman dekat jendela lebih subur, jadi cahaya matahari membantu tanaman tumbuh subur."}, {"lv": "C5", "vis": "🐾", "q": "Manakah pernyataan yang paling tepat tentang tumbuhan dan hewan?", "o": ["Tumbuhan tidak dapat bertambah besar", "Keduanya benda mati yang tidak bernapas", "Hanya hewan yang memerlukan makanan", "Keduanya makhluk hidup yang tumbuh dan memerlukan air"], "a": 3, "e": "Tumbuhan dan hewan sama-sama makhluk hidup: tumbuh, bernapas, dan memerlukan air serta makanan."}, {"lv": "C5", "vis": "🐱", "q": "Seorang pemilik kucing memberi makan kucingnya hanya dengan rumput setiap hari. Kucing itu menjadi lemah dan kurus. Penilaian yang paling tepat adalah ....", "o": ["Kucing adalah pemakan daging sehingga butuh makanan berprotein seperti ikan", "Kucing seharusnya tidak perlu makan", "Rumput adalah makanan terbaik untuk kucing", "Kucing menjadi kurus karena terlalu banyak bergerak"], "a": 0, "e": "Kucing termasuk karnivora. Rumput tidak cukup untuk kebutuhan gizinya, sehingga kucing perlu makanan berprotein seperti ikan atau daging."}, {"lv": "C5", "vis": "🐡", "q": "Rani ingin memelihara hewan di dalam akuarium. Hewan manakah yang paling tepat dipelihara Rani?", "o": ["Burung merpati", "Kucing", "Ikan hias", "Kambing"], "a": 2, "e": "Akuarium berisi air, jadi hanya hewan yang hidup di air seperti ikan hias yang cocok dipelihara di dalamnya."}, {"lv": "C5", "vis": "🍼", "q": "Manakah pasangan hewan dan anaknya yang tepat?", "o": ["Ayam dan anak kucing", "Katak dan cempe", "Sapi dan pedet", "Kucing dan berudu"], "a": 2, "e": "Anak sapi disebut pedet. Berudu adalah anak katak, sedangkan cempe adalah anak kambing."}, {"lv": "C5", "vis": "🦋", "q": "Manakah urutan daur hidup kupu-kupu yang benar?", "o": ["Telur - kepompong - ulat - kupu-kupu", "Ulat - telur - kupu-kupu - kepompong", "Telur - ulat - kepompong - kupu-kupu", "Kepompong - ulat - telur - kupu-kupu"], "a": 2, "e": "Kupu-kupu bertelur, telur menetas menjadi ulat, ulat menjadi kepompong, lalu kepompong menetas menjadi kupu-kupu dewasa."}, {"lv": "C5", "vis": "🌾", "q": "Manakah urutan rantai makanan di sawah yang paling tepat?", "o": ["Tikus - padi - elang - ular", "Elang - ular - padi - tikus", "Padi - tikus - ular - elang", "Ular - tikus - padi - elang"], "a": 2, "e": "Rantai makanan dimulai dari tumbuhan, lalu hewan pemakan tumbuhan, kemudian pemangsanya secara berurutan."}, {"lv": "C5", "vis": "🪴", "q": "Tanaman hias di kamar Dita tumbuh pucat dan layu walaupun disiram setiap hari. Tindakan yang paling tepat dilakukan Dita adalah ....", "o": ["Memindahkan tanaman ke tempat yang terkena cahaya matahari", "Memotong semua akar tanaman", "Menambah air hingga tanah tergenang", "Mengganti tanah dengan pasir kering"], "a": 0, "e": "Air sudah cukup, tetapi tanaman tetap pucat di kamar yang kurang cahaya. Memindahkannya ke tempat terang adalah tindakan yang tepat."}, {"lv": "C5", "vis": "🫘", "q": "Empat anak menanam biji kacang hijau dengan cara berbeda. Manakah cara yang paling tepat agar biji cepat berkecambah?", "o": ["Direndam dalam air panas mendidih", "Diletakkan di kapas kering di tempat gelap", "Diletakkan di atas meja tanpa air", "Diletakkan di kapas basah dan disimpan di tempat hangat"], "a": 3, "e": "Biji memerlukan air yang cukup dan suhu hangat untuk berkecambah. Air mendidih atau kapas kering membuat biji tidak tumbuh."}, {"lv": "C5", "vis": "🌿", "q": "Manakah bukti paling tepat yang menunjukkan bahwa tanaman yang dirawat Dito itu hidup?", "o": ["Tanaman bertambah tinggi dan bertambah daun", "Tanaman berwarna hijau", "Tanaman berdiri tegak di pot", "Tanaman berada dekat jendela"], "a": 0, "e": "Tumbuh dan bertambah besar adalah ciri makhluk hidup. Warna, posisi tegak, dan letak pot bukan bukti bahwa tanaman itu hidup."}, {"lv": "C5", "vis": "🚗", "q": "Manakah alasan yang paling tepat untuk menyatakan bahwa mobil-mobilan bukan makhluk hidup?", "o": ["Mobil-mobilan tidak tumbuh, tidak bernapas, dan tidak memerlukan makanan", "Mobil-mobilan berwarna cerah", "Mobil-mobilan berbentuk kecil", "Mobil-mobilan bergerak saat didorong"], "a": 0, "e": "Ciri makhluk hidup adalah tumbuh, bernapas, dan memerlukan makanan. Mobil-mobilan tidak memiliki ciri-ciri itu meskipun dapat bergerak saat didorong."}, {"lv": "C5", "vis": "🐤", "q": "Anak ayam yang baru menetas terlihat menggigil. Cara perawatan yang paling tepat adalah ....", "o": ["Menempatkannya di kandang yang hangat dan memberi makan serta minum", "Membiarkannya di luar rumah pada malam hari", "Menempatkannya di tempat yang dingin dan berangin", "Memberinya makan nasi dalam jumlah sangat banyak"], "a": 0, "e": "Anak ayam yang baru menetas belum bisa menghangatkan tubuhnya sendiri, sehingga perlu tempat hangat, makan, dan minum yang cukup."}, {"lv": "C5", "vis": "🏞️", "q": "Manakah pernyataan yang paling tepat tentang tempat hidup hewan?", "o": ["Tempat hidup hewan tidak berpengaruh bagi hidupnya", "Hewan air lebih kuat daripada hewan darat", "Hewan hidup di tempat yang sesuai dengan ciri tubuhnya", "Semua hewan dapat hidup di semua tempat"], "a": 2, "e": "Ciri tubuh hewan menyesuaikan tempat hidupnya. Ikan berinsang hidup di air, unta berpunuk hidup di padang pasir."}, {"lv": "C5", "vis": "🐦", "q": "Petani menyemprot kebunnya sehingga semua serangga di kebun itu mati. Burung pemakan serangga di kebun tersebut akan ....", "o": ["Tidak terpengaruh sama sekali", "Berubah menjadi pemakan padi", "Berkurang karena kekurangan makanan", "Makin banyak karena tidak ada serangga"], "a": 2, "e": "Serangga adalah makanan burung tersebut. Jika serangga habis, burung kehilangan sumber makanan sehingga jumlahnya berkurang."}, {"lv": "C5", "vis": "🏠", "q": "Manakah kandang yang paling baik untuk kesehatan hewan peliharaan?", "o": ["Kandang yang kotor tetapi diberi lampu terang", "Kandang yang penuh air agar hewan selalu dingin", "Kandang yang bersih, cukup luas, dan tidak lembap", "Kandang yang sempit dan selalu tertutup rapat"], "a": 2, "e": "Kandang yang bersih, cukup luas, dan tidak lembap membuat hewan nyaman dan terhindar dari penyakit."}, {"lv": "C5", "vis": "🐐", "q": "Manakah pernyataan yang paling tepat membandingkan daur hidup kupu-kupu dan kambing?", "o": ["Kupu-kupu mengalami perubahan bentuk (metamorfosis), kambing tidak", "Keduanya mengalami metamorfosis sempurna", "Anak kambing berbeda bentuk dengan induknya", "Kupu-kupu melahirkan anak, kambing bertelur"], "a": 0, "e": "Kupu-kupu berubah bentuk dari ulat menjadi kupu-kupu (metamorfosis), sedangkan anak kambing sejak lahir berbentuk sama seperti induknya."}, {"lv": "C6", "vis": "🌻", "q": "Kelompokmu ingin membuat kebun mini di dalam kelas. Rencana paling tepat agar tanaman di kebun mini itu tumbuh subur adalah ....", "o": ["Menyiram pot dengan air sangat banyak setiap hari dan menutup pot rapat-rapat", "Meletakkan pot di dalam lemari agar aman dan menyiram sekali seminggu", "Meletakkan pot di tempat gelap dan tidak perlu disiram", "Meletakkan pot di dekat jendela, menyiram teratur, dan memakai tanah yang subur"], "a": 3, "e": "Tanaman memerlukan cahaya, air yang cukup, dan tanah subur. Rencana itu memenuhi ketiga kebutuhan tersebut."}, {"lv": "C6", "vis": "🐇", "q": "Kamu diminta merancang kandang sederhana untuk kelinci peliharaanmu. Rancangan manakah yang paling tepat?", "o": ["Kandang cukup luas, beratap, berlantai mudah dibersihkan, serta ada tempat makan dan minum", "Kandang sangat kecil dan tertutup rapat tanpa lubang udara", "Kandang penuh air agar kelinci selalu basah", "Kandang tanpa atap agar kelinci terkena hujan langsung"], "a": 0, "e": "Kelinci perlu ruang gerak, udara segar, dan kandang bersih. Kandang yang luas, beratap, dan mudah dibersihkan adalah rancangan terbaik."}, {"lv": "C6", "vis": "🕸️", "q": "Guru meminta kamu menyusun rantai makanan dari kata berikut:\npadi, tikus, ular, elang\nUrutan rantai makanan yang tepat kamu susun adalah ....", "o": ["Padi - elang - ular - tikus", "Padi - tikus - ular - elang", "Elang - ular - tikus - padi", "Tikus - ular - padi - elang"], "a": 1, "e": "Rantai makanan dimulai dari tumbuhan, lalu pemakan tumbuhan, kemudian pemangsa berikutnya secara berurutan."}, {"lv": "C6", "vis": "🧪", "q": "Kamu ingin membuktikan bahwa tumbuhan memerlukan air. Rancangan percobaan yang paling tepat adalah ....", "o": ["Menyiapkan dua tanaman sejenis, satu disiram setiap hari dan satu tidak disiram, sedangkan hal lain dibuat sama", "Menyiapkan dua tanaman berbeda jenis dan menyiram keduanya dengan jumlah sama", "Menyiram semua tanaman dengan air panas setiap hari", "Meletakkan satu tanaman di tempat gelap dan satu di tempat terang, keduanya disiram"], "a": 0, "e": "Percobaan yang baik hanya mengubah satu hal, yaitu pemberian air. Jenis tanaman dan perawatan lain harus sama agar hasilnya dapat dipercaya."}, {"lv": "C6", "vis": "📋", "q": "Kamu ditugaskan membuat tabel daur hidup hewan dari telur sampai dewasa untuk kupu-kupu dan katak. Susunan yang tepat untuk kedua hewan itu adalah ....", "o": ["Kupu-kupu: telur - ulat - kepompong - kupu-kupu; katak: telur - kecebong - katak muda - katak dewasa", "Kedua hewan: telur - kecebong - kepompong - dewasa", "Kupu-kupu: telur - kepompong - ulat - kupu-kupu; katak: kecebong - telur - katak dewasa", "Kupu-kupu: ulat - telur - kupu-kupu; katak: katak dewasa - kecebong - telur"], "a": 0, "e": "Kupu-kupu: telur, ulat, kepompong, kupu-kupu dewasa. Katak: telur, kecebong, katak muda, katak dewasa. Keduanya mengalami metamorfosis dengan tahap yang berbeda."}];
